// v2 glossary (V2-SPEC §6.7). Owner: WS6. Starts from the v1 glossary, overrides every entry that carried a canon date
// or scenario reference (canon appears only on the end screen), and adds the v2 terms. Bodies link with [[id]].
import { GLOSSARY, type Term } from '../glossary';

const V2: Record<string, Term> = {
  // ── overrides of v1 entries (no canon dates) ──
  rdmult: { title: 'AI R&D multiplier M', body: 'Research speed of your lab ÷ the same lab with humans only (AI Futures\' AI R&D multiplier). It has two parts: [[effectiveLabour|AI labour]] in experiments and [[researchTaste|AI research taste]]. Before automation it is close to 1; agents add little until their [[coverage]] of the work rises.', src: 'research/13 §2.8; MODEL-V3 §6' },
  sc: { title: 'Superhuman Coder', body: 'A model whose software-engineering [[fit]] reaches the [[bestHuman|best human in the world]], with [[coverage]] ≥ 90% and an AI work-hour cheaper than your best engineers\'. As AI 2027 defines it. Level 10 on the display scale.', src: 'MODEL-V3 §6.4; research/13 §2.8' },
  sar: { title: 'Superhuman AI Researcher', body: 'The superhuman-coder test passed for experiments & runs and for research ideas & taste: fit at the [[bestHuman|best human]], coverage ≥ 90%. Level 12 on the display scale.', src: 'MODEL-V3 §6.4; research/13 §2.8' },
  siar: { title: 'Superintelligent AI Researcher', body: 'Research-ideas [[fit]] beyond the best human by twice the best-to-median gap (≈ 9 SD of human research taste). Level 13.5 on the display scale.', src: 'MODEL-V3 §6.4; research/13 §2.4' },
  asi: { title: 'Superintelligence', body: 'Every cognitive [[workType|work type]] beyond its best human by twice the best-to-median gap (level 15). The game resolves here: the outcome depends on the hidden [[misalign|misalignment]] of whoever gets there first and on who holds [[leverage]].', src: 'MODEL-V3 §6.4; V2-SPEC §5.2' },
  approval: { title: 'Net approval', body: 'Approve minus disapprove for your company (−100..+100). Moves with incidents, jobs, releases and disclosure.', src: 'research/07 §1.2' },
  salience: { title: 'Salience', body: 'Share of the public naming AI as the most important problem.', src: 'research/07 §1.2' },
  oversight: { title: 'Oversight committee', body: 'A joint company-government body that votes on key decisions. Can form late in the game when government [[securityDemand|security demand]] peaks.', src: 'research/07 §1.1' },
  cdz: { title: 'Centralized development zone', body: 'A state-run site where China pools its national compute under one lab.', src: 'research/10' },
  wsl: { title: 'Weight security level', body: 'WSL 1–5 (RAND). WSL n holds against an OC n attacker with high odds over two months. Raising it costs money and slows research ([[siloing]]).', src: 'RAND SL framework; research/17' },
  neuralese: { title: 'Neuralese', body: 'Latent reasoning and memory that is not readable text. Faster and cheaper to serve, but chain-of-thought monitors go blind: [[monitorability]] drops to 0.05. Needs paradigm P17 and a latent base [[shape]].', src: 'V2-SPEC §3.3.2, §3.5.1' },
  // ── v2 terms ──
  L: { title: 'Capability level L', body: 'General level 0–15 of your best internal model as MEASURED by your evals (noisy; [[sand|sandbagging]] biases it down). Milestones: 6.5 [[reliableAgent]], 8.5 [[researchAgent]], 10 [[sc]], 12 [[sar]], 13.5 [[siar]], 15 [[asi]].', src: 'V2-SPEC §3.1.5' },
  U: { title: 'Understanding U', body: 'The highest level at which your safety stack still detects the critical traits at 50% or better. Margin = U − L. Racing far ahead of U is how misaligned models ship unnoticed.', src: 'V2-SPEC §3.5.7' },
  prodfn: { title: 'Research production', body: 'Each project\'s experiments run at the AI Futures experiment CES of its own [[expCompute|compute c]] and [[expLabour|research-engineer labour ℓ]] (compute and labour are complements); ideation runs on scientists\' [[effectiveLabour|effective labour]] × [[researchTaste|taste]]. There is no lab-wide formula: lab [[researchSpeed|research speed]] is the sum over projects.', src: 'research/13 §1.3; MODEL-V3 §5.3' },
  bottleneck: { title: 'What binds', body: 'The input whose increase raises research most: [[computeBound|compute-bound]] (experiment compute), [[laborBound|labour-bound]] (research engineers and agents), [[humanBound|human-bound]] (labour, mostly human), [[tasteBound|taste-bound]] (late: which ideas to try). Read from the experiment CES at today\'s inputs.', src: 'research/13 §1.6' },
  runway: { title: 'Runway', body: 'Quarters until projected [[liquidity]] falls below minimum operating cash (one month of running costs), from a cash forecast over the next 8 quarters: revenue at today\'s run rate, running costs, and each payment in the quarter it falls due ([[ledger]] contracts, chip balances on delivery, site [[capex]] on its build schedule, unconditional tranches when they land). "8q+" means it lasts the whole forecast. [[healthy|Healthy]] ≥ 6q, [[tight|Tight]] 3–6q, [[distress|Distress]] < 3q.', src: 'research/15 §1.8' },
  parentBudget: { title: 'Parent budget', body: 'A big-tech division is funded by its parent: a fixed yearly budget on a schedule set in advance ($16B in the first year, growing with the parent’s capex), paid at the start of each quarter. Your product revenue goes to the parent. No equity raises, deals or debt, and you cannot go bankrupt: an overdraft is carried to the next payment.', src: 'research/18 §3.2; STRUCTURE §4.8' },
  startType: { title: 'Start type', body: 'Where your company begins: a frontier leader, a challenger lab, a big-tech AI division or a well-funded spinout. The rules are the same for all; only the start state differs. Difficulty is a label; scoring is the same.', src: 'STRUCTURE §4.8; research/18' },
  raiseCeiling: { title: 'Raise ceiling', body: 'The most you can raise this quarter: the smallest of your share of the [[investorPool|investor pool]], the [[dilutionCap|dilution cap]], the [[annualCap|annual cap]] and your ask.', src: 'research/15 §1.5' },
  scrutiny: { title: 'Scrutiny', body: 'How closely press, regulators and watchdogs watch you (0–100). High scrutiny speeds discovery of cover-ups and raises the odds of rules.', src: 'research/17 §1.1' },
  credibility: { title: 'Credibility', body: 'Whether outsiders believe your claims (0–100). Kept commitments raise it; broken ones and discovered cover-ups cost ×3.', src: 'research/17 §1.1' },
  trust: { title: 'Trust', body: 'Per-[[counterparty]] relationship stock (0–100). Trust unlocks [[access]] rungs and makes favors cheaper.', src: 'research/17 §1.1' },
  access: { title: 'Access rung', body: 'How deep a counterparty is involved: 0 none, 1 briefings, 2 early access, 3 pre-deployment testing, 4 embedded. Rungs need trust thresholds 25/45/65/80.', src: 'research/17 §1.1' },
  favors: { title: 'Favors', body: 'Tokens owed to you (max 5, they expire). Spent to soften rules or to unlock agreements.', src: 'research/17 §1.1' },
  commitment: { title: 'Commitment', body: 'A public promise with a condition (e.g. no BIO ≥ 10 deployment without classifiers). Keeping it builds [[credibility]]; breaking it costs the listed trust and credibility.', src: 'research/17 §1.2' },
  lead: { title: 'Lead days', body: 'Estimated days your best INTERNAL model is ahead of a rival or China (negative = behind). Built from public releases and evaluator reports; ± is the [[intelError|intel uncertainty]].', src: 'V2-SPEC §3.10.3' },
  leverage: { title: 'Leverage', body: 'The share of economic, governmental, military and infrastructure decisions routed through a lab\'s models (control index). Thresholds: [[entrenched]] 15%, [[indispensable]] 35%, [[decisive]] 60%.', src: 'research/16 §2' },
  agenda: { title: 'Safety agenda', body: 'Now called a [[researchLine|research line]]: a research programme (interpretability, control, evals, …) with a HIDDEN efficacy for this world. You see an estimate that narrows as [[finding|results]] arrive.', src: 'research/14 §1.2' },
  finding: { title: 'Finding', body: 'A research result. TECH unlocks a technique, EVAL an evaluation, DISC discovers a failure mode, DEAD ends an agenda, NEG weakens a technique, SPILL helps capabilities, FALSE looks like TECH but masks rather than detects.', src: 'research/14 §1.3' },
  technique: { title: 'Technique', body: 'A detector, fix or containment tool from a safety agenda. Strength decays as the overseen model grows past what the tool was validated on (halves at its [[halfStrength|half-strength point]]); training against it creates [[mask|masking]] ([[goodhart|Goodhart]]).', src: 'research/14 §1.4' },
  umode: { title: 'Unknown failure mode', body: 'A failure mode the trait graph does not model (U-mode). Incidents it causes show as "unexplained" until an agenda discovers it.', src: 'research/14 §1.6' },
  evalGate: { title: 'Eval gate', body: 'What must run before a new version can be used or sold: none, a basic suite, a full suite, or a deep suite plus external evaluators. A suite is work, not fixed days: research engineers (about 7 / 14 / 21 days at full staffing), a little engineer time and inference compute. Suites do not expire ([[autoEvaluate|auto-evaluate]] keeps the internal model current).', src: 'MODEL-V3 §10, V2-SPEC §3.3.5, R6' },
  monitorability: { title: 'Monitorability', body: 'How readable the model\'s reasoning is (0–1). Latent reasoning and CoT pressure lower it; CoT monitors only work while it is high.', src: 'research/14 §1.5' },
  sand: { title: 'Sandbagging', body: 'Deliberate underperformance on evaluations, mostly on dangerous-capability benchmarks. Makes measured L read low.', src: 'research/04' },
  index: { title: 'Safety Index', body: 'A semiannual outside grade of every lab across risk assessment, current harms, frameworks, existential safety, governance and information sharing.', src: 'FLI AI Safety Index; research/17 §1.6.2' },
  distill: { title: 'Distillation', body: 'Training a cheaper model on another model\'s outputs. API access lets rivals and China distill you; KYC levels slow it.', src: 'research/12' },
  kyc: { title: 'KYC level', body: 'Know-your-customer controls on API and agent channels (0–3). Each level cuts distillation access by a quarter and API/agent demand by 2%.', src: 'V2-SPEC §3.3.5' },
  hype: { title: 'Hype', body: 'Investor appetite index for AI. Moves the investor pool and valuation multiples.', src: 'research/15 §1.4' },
  boardConf: { title: 'Board confidence', body: 'Board confidence 0–100. Major decisions need approval; below 35 the board warns you ([[boardRevolt]]), below 25 it can vote you out ([[ouster]]).', src: 'V2-SPEC §3.7.5' },
  morale: { title: 'Morale', body: 'Staff morale 0–100. Scales productivity and attrition; safety staff morale reacts to safety decisions.', src: 'V2-SPEC §3.4.1' },
  M: { title: 'R&D multiplier', body: 'See [[rdmult]].' },
  split: { title: 'Compute split', body: 'How online compute is divided: [[poolTraining|Training]] (runs and [[poolSynthetic|data generation]]), [[poolResearch|Research]] (experiments and agents), [[poolServing|Serving]] and [[poolSafety|Safety]].', src: 'V2-SPEC §3.4.2' },
  wslTarget: { title: 'Security target', body: 'The [[wsl]] the security team builds toward; spending and siloing set the pace.' },
  ladderSec: { title: 'G-SEC ladder', body: 'Government security posture toward labs: 0 none, 1 briefings, 2 priority, 3 clearances, 4 oversight demands, 5 consolidation.', src: 'research/07 §1.1' },
  ladderChn: { title: 'China ladder', body: 'China\'s posture rung 0–6: coexistence, retaliation, acquisition, centralization, cyber operations, Taiwan pressure, war footing. The [[deesc|de-escalation track]] D1–D5 runs the other way.', src: 'research/10 §1.4' },
  sector: { title: 'Sector', body: 'One of 14 economic segments, each with its own [[workType|work type]], wage and employment. Firms hand tasks to AI ([[sectorA|automated share A]]) up to A* = [[feasibility]] × [[costGate|cost gate]] × (1 − [[friction]]); separately, [[workersUsingAI|workers use AI]] on the rest of their hours ([[hoursOfUse|hours of use]]). The [[binding]] limit is capability, cost, friction or diffusion.', src: 'research/16 §1A; research/22 §1; V4 and A2a notes' },
  paradigm: { title: 'Paradigm', body: 'A big capability idea (P05–P27) on the [[techTree|tech tree]]. Its [[odds]] are a known chance; whether it works is drawn per world. When it works it applies at once.', src: 'research/12 §0.7' },
  techTree: { title: 'Tech tree', body: 'Everything the lab can learn, in six lanes of expertise (science-team [[specialty|specialties]]). An idea opens when you know its prerequisites; there are no capability gates. Researching it is a project for science teams.', src: 'TECH-TREE §1' },
  knowHow: { title: 'Recipe', body: 'Your [[recipeStack|recipe stacks]] (pretraining, RL, serving & systems): the ideas your research adopted, in OOMs of effective compute. A new model embodies the recipe of its start; what it lacks is [[trainedIn|not trained in]].', src: 'MODEL-V3 §5' },
  trainedIn: { title: 'Not trained in', body: 'Recipe your internal model does not embody yet, in OOM: today\'s stack minus what its base (pretraining) or its post-training (RL) was trained with. A new base run trains the pretraining stack in, a post-training run the RL stack.', src: 'MODEL-V3 §3.1, §4.4' },
  depth: { title: 'Depth', body: 'Steps from what you know: depth 1 ideas need only known ideas; depth 2 need one more idea first, and so on.', src: 'TECH-TREE §1.1' },
  layer: { title: 'Layer', body: 'What using an idea needs: [[layerBackbone|Backbone]] (a new base), [[layerTraining|Training]] (post-training), [[layerScaffold|Scaffold]] (no training) or [[layerLab|Lab]] (applies at once).', src: 'TECH-TREE §1.4' },
  layerBackbone: { title: 'Backbone layer', body: 'Architecture, data, size: used by a new base run, then post-training.', src: 'TECH-TREE §1.4' },
  layerTraining: { title: 'Training layer', body: 'Post-training methods (RL, alignment training, reasoning style): used by a post-training run on an existing base.', src: 'TECH-TREE §1.4' },
  layerScaffold: { title: 'Scaffold layer', body: 'Inference-time: tools, memory, effort, safeguards, product features. No training needed.', src: 'TECH-TREE §1.4' },
  layerLab: { title: 'Lab layer', body: 'Research automation, detection tools, efficiency practices: they apply at once.', src: 'TECH-TREE §1.4' },
  effortClass: { title: 'Effort', body: 'How big a one-off idea is: S, M, L or XL. It sets the work of each [[projectStage|stage]] (ideation per candidate, small experiments, scale test) at the leader lab\'s day-0 inputs.', src: 'MODEL-V3 §5.3; design value' },
  teamMonth: { title: 'Team-month', body: 'One standard team for a month at the leader lab\'s day-0 inputs: a science team for ideation, two research-engineering team-equivalents with their experiment compute for experiments. Faster inputs do a team-month\'s work in less time.', src: 'MODEL-V3 §5.3' },
  odds: { title: 'Odds', body: 'The chance a one-off idea or axis works in this world, shown before you start. The result is drawn per world: if three candidates in a row are dropped, the project fails, and you can [[reopenSpeculative|reopen it as speculative]] at half the odds. Lines always produce results (smaller over time). Safety ideas take their odds from a [[researchLine|research line]].', src: 'MODEL-V3 §5.3' },
  researchLine: { title: 'Research line', body: 'A safety research programme (interpretability, control, evals, …). Safety science teams work its ideas on the tree; each finished project gives one result: a working tool, a weaker one, a [[deadEnd|dead end]], a discovery. How well the line really works is hidden; you see its [[lineHealth|health]].', src: 'TECH-TREE §1.3, STRUCTURE §4.5' },
  lineHealth: { title: 'Line health', body: 'Promising, Mixed or Struggling: the estimated chance that a result on this line is a working tool, from the results so far (a Beta estimate with a 90% band). The true efficacy is hidden and differs by world.', src: 'STRUCTURE §4.5' },
  deadEnd: { title: 'Dead end', body: 'A result that goes nowhere. The team-months spent on that attempt count as lost; the line estimate drops, and a line whose estimate falls below 25% runs at half speed.', src: 'STRUCTURE §4.5' },
  seriousStaffing: { title: 'Serious staffing', body: 'About four matching safety science teams on a line (capacity 4: people ÷ 40 × quality × 1.5 in the team specialty). At serious staffing a line gets its first result after its T₁ months; results come faster with √ capacity, safety compute and [[trustedToAI|AI labour]].', src: 'TECH-TREE §4' },
  followUp: { title: 'Follow-up', body: 'The open-ended project of a research line once its ideas are known: more results (sharper tools, measured evidence, discoveries, or dead ends).', src: 'STRUCTURE §4.5' },
  toolUpkeep: { title: 'Tool upkeep', body: 'Safety research engineers not on cases or research-line experiments re-validate tools that start to fade on your newest model, raising their [[halfStrength|half-strength point]] so they keep working as capability grows. No ceiling and no projects to click. Re-validating a tool takes a crew (about 15 engineers); beyond that, more engineers per fading tool means faster upkeep. Free engineers also set how far ahead of your model the tools are validated.', src: 'TECH-TREE §2.6' },
  validatedTo: { title: 'Tools validated to', body: 'The capability level at which your typical detection tool loses half its strength. [[toolUpkeep|Tool upkeep]] raises it; once capability passes it, your tools stop seeing the model.', src: 'STRUCTURE §4.5' },
  blind: { title: 'Blind', body: 'Capability above [[U|understanding]]: levels at which your tools can no longer see the critical traits.', src: 'STRUCTURE §4.5' },
  caseStaffing: { title: 'Case staffing', body: '5–40 safety research engineers per case. Clarity grows with √(people ÷ 15); the engineers come out of [[toolUpkeep|tool upkeep]] while the case runs (at most 120 days).', src: 'V2-SPEC §3.5.8' },
  specialtyBonus: { title: 'Specialty bonus', body: 'A science team works ×1.5 on ideas in its own lane, ×1.0 elsewhere.', src: 'TECH-TREE §5 T2' },
  diminishingReturns: { title: 'Diminishing returns', body: 'Progress grows with the square root of a project’s capacity: two teams are √2 ≈ 1.4× one team, so spreading teams over projects often beats piling them on one.', src: 'TECH-TREE §1.2' },
  projectQueue: { title: 'Priority list', body: 'Your capability projects in order. The game puts science teams down the list (each project up to its [[teamsWanted|teams wanted]], best specialty first, then one swap pass), gives research engineers and experiment compute to the projects in experiments in this order, and leaves the rest waiting. Drag, ▲▼, or Alt+↑ / Alt+↓ on a focused row to reorder.', src: 'MODEL-V3 §5.6' },
  autoAssign: { title: 'Auto-assign (safety)', body: 'Policy for safety science teams: idle teams join the highest-priority ready safety project in their specialty; a team whose project resolves keeps working its research line. Capability teams are always placed by the [[projectQueue|priority list]].', src: 'MODEL-V3 §5.6' },
  retryRule: { title: 'Retry', body: 'A failed safety idea can be tried again 180 days later, at half the odds. Capability projects do not wait: you can [[reopenSpeculative|reopen them as speculative]] at once.', src: 'TECH-TREE T1; MODEL-V3 §5.3' },
  // ── race / top strip ──
  gap: { title: 'Understanding gap', body: 'U − L. Negative is a BLIND gap: your best model is more capable than your tools can read, so hidden traits grow faster and go unseen. Positive means your tools are AHEAD.', src: 'V2-SPEC §3.5.4, §3.5.7' },
  evaluating: { title: 'Evaluating', body: 'A finished version is still in its eval suite (at the [[evalGate|eval gate]] depth; it takes as long as the research engineers on evals need for it). Until it ends, the L shown is the lineage\'s last measured level, and the version cannot be used or launched.', src: 'MODEL-V3 §10, V2-SPEC §3.3.5' },
  catRisk: { title: 'Catastrophe risk estimate', body: 'Estimated P(catastrophe | today\'s trajectory): the [[riskSource|risk sources]] combined. Built from your beliefs and intel, never the truth, so it is shown as a band.', src: 'V2-SPEC §6.6' },
  riskSource: { title: 'Risk source', body: 'One path to catastrophe: your own models, each rival, China, misuse (bio, cyber), theft, rogue copies, war. Each row has an estimate band, its drivers and the levers that reduce it.', src: 'V2-SPEC §6.6' },
  reliableAgent: { title: 'Reliable agent', body: 'Your models cover 50% of software-engineering work ([[coverage]]). Opens Act 2.', src: 'MODEL-V3 §6.4; V3 notes' },
  researchAgent: { title: 'Research agent', body: 'Your models cover 50% of experiments-and-runs work ([[coverage]]). Opens Act 3 and safety [[automateSafety|automation]].', src: 'MODEL-V3 §6.4; V3 notes' },
  milestone: { title: 'Milestone', body: 'A statement about [[workType|work types]]: agent and reliable agent (software coverage 10% and 50%), research agent (experiments coverage 50%), [[sc]], [[sar]], [[siar]], [[asi]]. A lab crosses it when any of its live versions, internal ones included, meets it; rollbacks never undo it. Company › Work shows how far each criterion is.', src: 'MODEL-V3 §6.4' },
  intelError: { title: 'Intel uncertainty', body: 'The ± on a [[lead]] estimate: one standard deviation in days. It shrinks with evidence: public releases, evaluator access, known incidents and thefts.', src: 'V2-SPEC §3.10.3' },
  act: { title: 'Act', body: 'Pacing stage that unlocks panels. 1 Startup; 2 Frontier race at measured L ≥ 6.5 or day 150; 3 Automation at L ≥ 8.5; 4 Takeoff at L ≥ 12 or [[rdmult|M]] ≥ 25. Turning the tutorial off unlocks everything.', src: 'V2-SPEC §1.5, §6.8' },
  watch: { title: 'Watch list', body: 'Up to four problems found by rules on what you can see: idle chips, capped deployments, weak detection, runway, stale evals, board, morale. Each shows cause → effect and a Go button to the fix.', src: 'design/ux/IA.md' },

  // ── money ──
  cash: { title: 'Cash', body: 'Money in the bank ($B). Every inflow and outflow is booked and explained. If cash stays below zero for 30 days with no options left, you are insolvent.', src: 'V2-SPEC §3.7.6' },
  liquidity: { title: 'Liquidity', body: 'What [[runway]] counts as available: cash + the undrawn [[revolver]]. The revolver drops out in [[distress]]. Unconditional tranches enter the forecast in the quarter they land.', src: 'research/15 §1.8' },
  burn: { title: 'Burn', body: 'Gross spending per quarter: [[opex]], [[ledger]] commitments, chip balances and site [[capex]] falling due.', src: 'research/15 §1.8' },
  netBurn: { title: 'Net burn', body: '[[burn|Burn]] minus revenue, per quarter, averaged over the next 4 quarters of the [[runway]] forecast. Zero or negative means you are self-funding.', src: 'research/15 §1.8' },
  revenueNow: { title: 'Revenue now', body: 'One product\'s revenue today, annualised ($B/yr): demand served at its price. Product cards and edit previews show it; the top strip shows the [[revenueRun|30-day average]] of all products, which trails it.', src: 'V2-SPEC §3.11.3' },
  revenueRun: { title: 'Revenue run-rate', body: 'Revenue annualised and averaged over 30 days ($B/yr), the figure in the top strip. Drives [[valuation]], the [[annualCap|annual cap]], [[revolver]] size and the board\'s revenue plan (+15% per quarter).', src: 'V2-SPEC §3.7.2, §3.11.3' },
  valuation: { title: 'Valuation', body: 'What investors think the company is worth: about 22 × revenue, scaled by growth, [[hype]], your narrative premium and [[rates]]. Each priced round resets it to the post-money.', src: 'research/15 §1.5' },
  capex: { title: 'Capex', body: 'Capital spending: chips (deposits and balances on delivery) and site construction by stage. Chips dominate; compute costs dwarf payroll.', src: 'V2-SPEC §3.7.6' },
  opex: { title: 'Opex', body: 'Running costs outside the [[ledger]]: [[payroll]], security spend, power and O&M, interest, spot rentals, revenue shares and the transition fund.', src: 'V2-SPEC §3.7.6' },
  payroll: { title: 'Payroll', body: 'Staff cost, paid monthly, per person-year: engineers $0.70M; research engineers $0.80M (safety $0.65M); scientists $1.00M (safety $0.80M); × [[teamQuality|quality]] (Solid 0.8, Strong 1, Elite 1.6). People already hired into a [[hiringQueue|queued team]] are paid. Small next to compute.', src: 'research/19 §1.2' },
  dilution: { title: 'Dilution', body: 'The share of the company a round sells: amount / post-money. Every holder shrinks pro rata. Rounds above 10% need board approval.', src: 'research/15 §1.5' },
  dilutionCap: { title: 'Dilution cap', body: 'Most one round may sell: 8% to financial investors, 14% with an [[anchorPartner|anchor partner]], 5% at an [[ipo|IPO]]. One limit of the [[raiseCeiling|raise ceiling]].', src: 'research/15 §1.5' },
  annualCap: { title: 'Annual cap', body: 'Most equity investors will put in over four quarters: k × revenue run-rate minus what you already raised, with k = 5 at $10B revenue, falling as revenue grows.', src: 'research/15 §1.5' },
  investorPool: { title: 'Investor pool', body: 'This quarter\'s appetite for frontier-lab equity: sector revenue × [[hype]] × [[rates]] factor. Your share grows with valuation, momentum and governance; unused appetite carries over at 50%.', src: 'research/15 §1.4' },
  anchorPartner: { title: 'Anchor partner', body: 'A strategic investor taking at least 40% of a round. Raises the [[dilutionCap|dilution cap]] to 14%. Each partner anchors only one lab at a time.', src: 'V2-SPEC §3.7.3–3.7.4' },
  repricedRound: { title: 'Repriced round', body: 'At close, investors marked your round more than 25% below its term sheet and below the last post-money. You choose: accept it as a [[downRound|down round]] (cash, dilution, board confidence −15, senior attrition) or pull it (no cash). Undecided after 30 days, it is pulled.', src: 'research/15 §1.5' },
  downRound: { title: 'Down round', body: 'Raising below the last post-money: offered only when runway is [[tight]] or in [[distress]], at 50–70% of value. Board confidence −15, senior attrition, and anti-dilution shares for prior investors.', src: 'research/15 §1.5, §1.8' },
  rescue: { title: 'Strategic rescue', body: 'In [[distress]] a hyperscaler or sovereign takes up to a 30% stake for cash (about two quarters of burn, at least $20B), a double-weight board seat, exclusivity and IP rights. At most one per year.', src: 'V2-SPEC §3.7.5–3.7.6' },
  recap: { title: 'Recapitalisation', body: 'Legacy-nonprofit preset only: restructure into a for-profit (about four quarters of attorney-general review, scrutiny up) to free a conditional growth tranche. Refusing cuts the tranche from $30B to $10B.', src: 'V2-SPEC §3.7.5' },
  ipo: { title: 'IPO', body: 'A public listing. The round may sell only 5%, but taps a one-time public investor pool; adds an independent board seat and opens bond markets.', src: 'research/15 §1.5' },
  ownership: { title: 'Ownership', body: 'Who holds the company: founders and staff, the mission entity, financial investors, strategic partners and the public. Outside ownership pushes the board toward speed and returns.', src: 'V2-SPEC §3.7.2, §3.7.4' },
  boardSeat: { title: 'Board seat', body: 'A vote on major decisions, weighted by seat. Each seat has a stance on speed, finance, safety and mission. Strategic seats veto deals with that partner\'s competitors.', src: 'V2-SPEC §3.7.4–3.7.5' },
  boardRevolt: { title: 'Board revolt', body: 'The warning: [[boardConf|board confidence]] below 35 at a quarterly review. It clears back at 45. Without it, no ouster vote can be called.', src: 'V2-SPEC §3.7.5' },
  ouster: { title: 'Ouster', body: 'With confidence below 25 and a warning at least 60 days old, the board may vote to replace you (15% per quarter). If staff morale is above 70, a staff revolt can reinstate you once.', src: 'V2-SPEC §3.7.5' },
  ledger: { title: 'Commitment ledger', body: 'Contracted payments by quarter: cloud, chip LTAs, leases, SPV leasebacks, vendor and power contracts. Each is [[firmCommit|firm]] or [[cancellable]]. Commitments above 3× revenue need the board.', src: 'V2-SPEC §3.7.6' },
  firmCommit: { title: 'Firm commitment', body: 'A non-cancellable ledger payment (take-or-pay). You owe it whatever happens; it counts in [[runway]] and the [[rating]].', src: 'research/15 §1.8' },
  cancellable: { title: 'Cancellable', body: 'A commitment you can exit with notice (in quarters) and a penalty. Cancellable cloud costs 15% more. In distress you can cancel to cut burn.', src: 'research/15 §1.8' },
  covenant: { title: 'Covenant', body: 'A lender\'s test each quarter end. A drawn revolver needs cash ≥ max($1B, 11% of revenue); GPU loans need chip value ≥ 1.2× the loan or cash is swept. A breach means [[distress]].', src: 'research/15 §1.7' },
  rating: { title: 'Credit rating', body: 'BBB, BB, B or closed, from cash flow, backlog, debt and commitments vs revenue. Sets bond spreads. Closed shuts credit markets except vendor notes.', src: 'research/15 §1.7' },
  revolver: { title: 'Revolver', body: 'A committed credit line (starts at $4B, grows to a third of revenue up to $15B; SOFR + 2%). Draw and repay freely; it covers negative cash automatically. Frozen in [[distress]]; carries a liquidity [[covenant]].', src: 'research/15 §1.7' },
  gpuTerm: { title: 'GPU-backed loan', body: 'A term loan secured on your chips: up to 60% of their value, SOFR + 4.75%, 4 years. If chip value falls below 1.2× the loan, cash is swept to pay it down.', src: 'research/15 §1.7' },
  bond: { title: 'Bond', body: 'Long debt (10 years) at the 10-year yield plus a [[rating]] spread. Only with revenue above $50B or a listing; up to 1× revenue.', src: 'research/15 §1.7' },
  vendorNote: { title: 'Vendor note', body: 'A supplier lends you the money to pay it (vendor financing deal). Counts as debt and a commitment; converts at an IPO. Available even when the rating is closed.', src: 'research/15 §1.7' },
  spv: { title: 'Project-finance SPV', body: 'Outside capital pays 80% of a site; you lease it back (12%/yr, 4 years) and guarantee its residual value. Off-balance-sheet: board confidence −2 per quarter.', src: 'research/15 §1.7' },
  deal: { title: 'Strategic deal', body: 'A partnership template: hyperscaler equity, custom ASIC, chip-vendor equity, vendor financing, sovereign, SPV, neocloud take-or-pay, mega-JV. Each trades capital or compute for strings: seats, exclusivity, commitments.', src: 'V2-SPEC §3.7.4' },
  bubble: { title: 'Bubble', body: 'Pressure X = sector commitments and capex / sector revenue. Above 3 a bust gets likely (up to 12% per quarter): investor pool −60%, hype crashes, credit spreads widen.', src: 'research/15 §1.4' },
  rates: { title: 'Rates', body: 'The 10-year yield (y10, a random walk around 4.5%) and SOFR (y10 − 0.3). Higher rates shrink valuations and the investor pool. Loans price over SOFR, bonds over y10.', src: 'V2-SPEC §3.7.4' },
  distress: { title: 'Distress', body: 'Runway under 3 quarters or a covenant breach. Revolver frozen, no priced rounds, debt +3%, morale hit. Options: [[downRound|down round]], [[rescue]], renegotiate, sell chips, cancel contracts.', src: 'research/15 §1.8' },
  tight: { title: 'Tight', body: 'Runway of 3–6 quarters. Investors offer 20% less, board confidence −5 a quarter, and the distress menu opens early. Fast-forward stops when you enter it.', src: 'research/15 §1.8' },
  healthy: { title: 'Healthy', body: 'Runway of 6 quarters or more. Full access to the investor pool and credit.', src: 'research/15 §1.8' },

  // ── compute ──
  computeOnline: { title: 'Compute online', body: 'H100e you can use today: chips installed in live sites (limited by [[mw|MW]]) plus cloud contracts and spot rentals. Divided into [[pool|pools]] by the compute split.', src: 'V2-SPEC §3.8' },
  idleChips: { title: 'Idle chips', body: 'Delivered chips with no rack space: every live site is full. They earn nothing and lose 6% of their value each quarter until new [[mw|MW]] goes live. Chips that fit are [[installing]], not idle.', src: 'research/15 §1.3' },
  listPrice: { title: 'List price', body: 'Price per H100e for standard orders ($K): chip cost × supplier markup, plus a premium when demand outruns supply. Cost falls about 8% a quarter.', src: 'research/15 §1.2' },
  spotPrice: { title: 'Spot price', body: 'Price of a spot chip order: [[listPrice|list price]] plus half the shortage premium. No deposit, delivered next quarter, lowest priority in rationing.', src: 'research/15 §1.2' },
  rental: { title: 'Rental rate', body: 'Spot cloud price per H100e-hour: 1.6 × owned cost, rising with demand/supply. Spot rentals last a quarter and are capped at 10% of the rental pool.', src: 'research/15 §1.2' },
  cloudContract: { title: 'Cloud contract', body: 'Rented capacity for years at 1.6 × owned cost. Starts next quarter and needs no MW of your own. Take-or-pay; the cancellable kind costs 15% more.', src: 'research/15 §1.2' },
  lta: { title: 'Long-term agreement', body: 'Chips every quarter for 4–12 quarters at 95% of list, from two quarters after signing. Take-or-pay through the [[ledger]]: one payment per tranche, from the first delivery. After 4 quarters it raises your [[allocation]] weight by 0.5.', src: 'research/15 §1.2' },
  allocation: { title: 'Allocation', body: 'When supply is short, orders are rationed. Fill share = what you got of last quarter\'s due orders. Order weight = 1 + 0.5 aged LTA + 0.5 prepay + 0.5 strategic chip deal + 0.3 track record.', src: 'research/15 §1.2' },
  exportPolicy: { title: 'Export policy', body: 'US chip export controls: strict, case-by-case or open. Sets China\'s share of global chip supply (1% / 6% / 12%, plus smuggling) and so its compute.', src: 'research/15 §1.2; research/10' },
  taiwanRisk: { title: 'Taiwan risk', body: 'Most leading chips come from Taiwan (93% falling to 75%). A quarantine cuts supply for quarters, spikes prices and loses chips in transit. Odds rise with [[taiwanTension|tension]]. Non-Taiwan allocation costs 30% more.', src: 'research/15 §1.2' },
  packaging: { title: 'Packaging', body: 'Advanced chip packaging capacity (H100e per quarter). One of three supply components; global supply is the smallest of [[packaging]], [[hbm|HBM]] and [[wafer|wafers]]. Expands in about 4 quarters; funding a supplier reserves output.', src: 'research/15 §1.2' },
  hbm: { title: 'HBM', body: 'High-bandwidth memory capacity. One of three supply components; about 6 quarters to expand. Exposed to Korea disruption.', src: 'research/15 §1.2' },
  wafer: { title: 'Wafers', body: 'Leading-edge wafer capacity. The slowest supply component (about 16 quarters to expand); expected to bind later in the game.', src: 'research/15 §1.2' },
  mw: { title: 'MW', body: 'Facility power capacity of your sites. Chips run only where there is power: H100e capacity = MW × 1000 / [[kwPerH100e]].', src: 'research/15 §1.3' },
  kwPerH100e: { title: 'kW per H100e', body: 'Facility power each H100e of compute needs, including cooling. Falls every quarter as chips get more efficient, so the same MW holds more compute.', src: 'research/15 §1.3' },
  transformers: { title: 'Transformers', body: 'Large power transformers: 8–10 quarter lead time. Brownfield, grid and nuclear sites wait for them unless you pre-order (20% deposit).', src: 'research/15 §1.3' },
  gridPool: { title: 'Grid pool', body: 'New US grid capacity for large loads each quarter (starting 1.5 GW, growing 25%/yr), shared by everyone. Grid sites need a slot; when it runs out they slip a quarter.', src: 'research/15 §1.3' },
  site: { title: 'Site', body: 'A data centre. Moves through [[permitting]] → power → construction → live (or blocked). Choose a [[siteTier|size]], a [[sitePath|power source]], [[crashBuild|crash build]] and [[communityPackage|community deal]].', src: 'V2-SPEC §3.8' },
  sitePath: { title: 'Power source', body: 'Colo (lease): fastest, no block risk, network capex only. Brownfield: ≤ 1 GW, power in 4–8q. Gas: ≤ 2.5 GW, 6–12q, costlier power, more opposition. Grid: ≤ 5 GW, 12–24q, needs the [[gridPool|grid pool]]. Nuclear: ≤ 1 GW, 12–20q, cheap power.', src: 'research/15 §1.3' },
  permitting: { title: 'Permitting', body: 'The first site stage. At its end local opposition can block the site (capex spent is lost) or delay it 1–3 quarters. Odds rise with public data-centre opposition, gas and crash builds.', src: 'V2-SPEC §3.8' },
  crashBuild: { title: 'Crash build', body: 'Build in 4 quarters instead of 8, at +35% capex and higher block risk.', src: 'research/15 §1.3' },
  communityPackage: { title: 'Community deal', body: 'Community benefits agreement for a site in permitting: +3% capex, halves the odds of being blocked.', src: 'research/15 §1.3; research/17 F1' },
  installing: { title: 'Installing', body: 'Delivered chips that fit in free racks. They are racked and online at the start of next quarter.', src: 'research/15 §1.3' },
  emptyRacks: { title: 'Empty racks', body: 'Powered capacity in your live sites with no chips in it. You pay for the building and its upkeep; it adds no compute until chips arrive. Racks grow each quarter as [[kwPerH100e|kW per H100e]] falls.', src: 'research/15 §1.3' },
  poweredCapacity: { title: 'Powered capacity', body: 'The most compute you could run: H100e that fit in your live sites ([[mw|MW]] ÷ [[kwPerH100e|kW per H100e]]) plus [[cloudContract|cloud]] in force. Chips beyond it sit [[idleChips|idle]].', src: 'research/15 §1.3' },
  vendorFill: { title: 'Vendor fill', body: 'Share of your due chip orders the vendors delivered last quarter. Below 100% when supply is short and orders are rationed by [[allocation]] weight.', src: 'research/15 §1.2' },
  siteTier: { title: 'Data-centre size', body: 'Hall 100 MW (one AI data hall) · Building 300 MW · Campus 1 GW (the largest live sites in 2026) · Large campus 2.5 GW · Multi-GW campus 5 GW. Colo, brownfield and nuclear top out at a campus; gas at a large campus; only the grid reaches 5 GW.', src: 'Epoch AI data centers hub; research/15 §1.3' },
  colo: { title: 'Colo (colocation lease)', body: 'Lease racks in a third-party data centre: live in 1–3 quarters, no permits, no block risk. You pay network fit-out plus a 5-year lease (about 12%/yr of the facility). Limited by the colocation capacity on the market each quarter.', src: 'research/15 §1.3' },
  brownfield: { title: 'Brownfield', body: 'Reuse an industrial site with an existing grid connection: up to 1 GW, power in 4–8 quarters, needs [[transformers]].', src: 'research/15 §1.3' },
  gasPower: { title: 'Gas (on-site)', body: 'Your own gas turbines: up to 2.5 GW, power in 6–12 quarters, no grid queue. Power costs 1.3× grid and local opposition is likelier.', src: 'research/15 §1.3' },
  gridPower: { title: 'Grid', body: 'A new utility interconnection: up to 5 GW, but 12–24 quarters to power and a slot in the [[gridPool|grid pool]]. Needs [[transformers]].', src: 'research/15 §1.3' },
  nuclearPower: { title: 'Nuclear', body: 'Power from a nuclear plant (restart or co-location): up to 1 GW, 12–20 quarters, highest capex, cheapest power (0.8×).', src: 'research/15 §1.3' },
  pool: { title: 'Compute pools', body: 'Online compute divided by the [[split|compute split]]: [[poolTraining|training runs]], [[poolSynthetic|data generation]], [[poolExperiments|experiments]], [[poolAgents|agents]], [[poolServing|serving]], [[poolSafety|safety]].', src: 'V2-SPEC §3.4.2' },
  poolTraining: { title: 'Training pool', body: 'Compute for training runs. Its FLOP per day sets how fast runs finish; each run takes a share. See [[trainingPool]].', src: 'V2-SPEC §3.3.1' },
  poolExperiments: { title: 'Experiments pool', body: 'Compute for research experiments: the compute input of the [[prodfn|production function]] and of paradigm projects.', src: 'V2-SPEC §3.2.1' },
  poolAgents: { title: 'Agents pool', body: 'Inference for your internal AI researchers: copies of the [[internalAgent|internal agent]] doing capabilities research. Part of [[poolResearch|Research]]; the [[researchMix|mix]] sets how much.', src: 'V2-SPEC §3.2.1, §3.4.2' },
  poolSynthetic: { title: 'Data generation', body: 'Training compute that generates synthetic data. It builds the data stock that new bases need; below the requirement a base hits the [[dataWall|data wall]] and loses capability. It does not speed up research.', src: 'V2-SPEC §3.2.2, §3.3.2' },
  poolServing: { title: 'Serving pool', body: 'Compute that serves customers. Each external deployment reserves a [[servingShare|share]]; too little makes it [[capacityBound|capacity-bound]].', src: 'V2-SPEC §3.11.3' },
  poolSafety: { title: 'Safety pool', body: 'Compute for safety agendas, investigations, [[runtimeMonitoring|runtime monitoring]] and [[safetyAgents|safety agents]]. See [[safetyLoad|department load]] for what it is doing.', src: 'V2-SPEC §3.5.2' },
  poolResearch: { title: 'Research compute', body: 'Experiments plus capabilities agents: the compute that speeds up your research. Split between them by the [[researchMix|research mix]].', src: 'V2-SPEC §3.4.2' },
  poolHumans: { title: 'Researchers', body: 'Your capabilities staff, the human input of the [[prodfn|production function]]. They matter less as AI does more of the coding.', src: 'research/13 §1.3' },
  researchMix: { title: 'Research mix', body: 'Share of research compute on experiments; the rest runs agents. Auto re-sets the best mix every day, for your staff, model and compute. The chart shows research speed for every mix.', src: 'research/13 §1.3' },
  responseCurve: { title: 'Input response', body: 'Research speed if one input were ×¼ to ×4 of today, the others held. A steep line is your bottleneck; a flat one is saturated, so more of it buys little.', src: 'research/13 §1.6' },
  safetyLoad: { title: 'Department load', body: 'What safety staff and safety compute are doing: research lines, investigations, tool upkeep, monitoring, agents, and what is idle.', src: 'V2-SPEC §3.5.2' },
  safetyAgents: { title: 'Safety agents', body: 'AI copies doing safety research: the Safety research lane of [[agentPackage|Agents at work]], on a share of the safety pool. Pick the model there: an older trusted one is weaker but carries its own, lower sabotage risk. [[trustedToAI|Trusted to AI]] decides how much safety work they do.', src: 'STRUCTURE §4.9' },
  computeBound: { title: 'Compute-bound', body: 'More experiment compute would speed research more than more labour (people or AI) would: the compute term of the experiment CES binds.', src: 'research/13 §1.6' },
  laborBound: { title: 'Labour-bound', body: 'More research engineers or more research agents would speed research more than more experiment compute would.', src: 'research/13 §1.6' },
  humanBound: { title: 'Human-bound', body: 'Labour-bound, and people still carry most of the labour margin ([[humanShare|humans\' share]] > 50%): hire, or give the agents work they cover.', src: 'research/13 §1.6' },
  tasteBound: { title: 'Taste-bound', body: 'Late: AI research taste is most of the AI R&D multiplier, so which ideas get tried matters more than compute or labour.', src: 'research/13 §1.6' },
  experiments: { title: 'Experiment compute', body: 'Compute spent testing ideas, measured against a reference path. Research needs it alongside labour: agents without experiments hit a ceiling.', src: 'research/13 §1.2' },
  researchTaste: { title: 'Research taste', body: 'Skill at choosing ideas: research input per idea, 1 for a Strong science team without AI. A team\'s taste is the better of its people (Solid −0.5, Strong 0, Elite +1 SD of the lab\'s taste distribution, stars ×1.05 each) and the frontier-research model\'s AI taste (SDs above the median expert). Taste raises a candidate\'s expected effect and narrows the belief noise.', src: 'research/13 §2.4; MODEL-V3 §8' },
  aiFte: { title: 'AI FTE', body: 'AI labour in human full-time equivalents: agent compute ÷ (H100e-hours per human work-hour) ÷ 2,000 hours a year. A work-hour costs the tokens an hour of agentic work processes (200k uncached input, 40k output) at the model\'s FLOP per token.', src: 'research/20 D1–D2; MODEL-V3 §6.3' },
  agentCopies: { title: 'Agent copies', body: 'Agents running at once: work-hours per hour ÷ their serial speed (60 tokens/s per copy ≈ 5× a human, capped at 50×). Smaller or more serving-efficient models run more copies on the same compute.', src: 'research/20 D1; MODEL-V3 §6.3' },
  nextModelGate: { title: 'Next-model gate', body: 'What limits your next frontier base run: [[trainingDays|training days]], data ([[dataWall|data wall]]), free MW, or cash.', src: 'V2-SPEC §3.2.5' },
  dataWall: { title: 'Data repetition', body: 'A base trains on its tokens (active parameters × tokens per parameter). It draws them from your data portfolio by its [[dataMix|data mix]]; a domain drawn beyond its unique tokens repeats them: up to ~4 epochs is nearly free, beyond that each repeat is worth less (Muennighoff et al. 2023, per domain), valued as a share of effective compute. More data (synthetic generation, licences, usage) pushes it back.', src: 'MODEL-V3 §3.2; research/20 A3' },
  trainingDays: { title: 'Training days', body: 'Days your training pool needs to deliver a reference-size frontier base run (the readout of the next-model gate). Runs have no maximum or minimum length.', src: 'V2-SPEC §3.2.5; MODEL-V3 §3.3' },

  // ── people / security ──
  headcount: { title: 'Headcount', body: 'People on your [[team|teams]]: capabilities (engineers, research engineers, scientists) and safety (research engineers, scientists).', src: 'STRUCTURE §4.1' },
  team: { title: 'Team', body: 'Staff come in whole teams of fixed size: [[roleEng|engineering]] 150, [[roleRE|research engineering]] 100, [[roleSci|science]] 40. Attrition leaves vacancies that hiring refills first.', src: 'STRUCTURE §4.1' },
  roleEng: { title: 'Engineers', body: 'Software, infrastructure and product engineers: one shared pool that runs and builds things (training runs, product upkeep, monitors in production, launches, features, sector packs). Output: [[buildCapacity|build capacity]]. Taken over by AI first.', src: 'research/19 §1.1' },
  roleRE: { title: 'Research engineers', body: 'Routine research: experiments, scaling, validation. Capabilities research engineers set your research labour: h = research engineers ÷ (0.55 × the reference lab\'s staff). Safety ones keep detection tools valid and run investigations. Taken over by AI second.', src: 'research/19 §1.1' },
  roleSci: { title: 'Scientists', body: 'Frontier research. Capabilities science teams run the research projects on the [[techTree|tech tree]] (×1.5 in their [[specialty]]); their quality also drives [[researchTaste|research taste]]. Taken over by AI last.', src: 'research/19 §1.3' },
  teamQuality: { title: 'Team quality', body: 'Solid ×0.8 output at ×0.8 cost; Strong ×1 (the reference); Elite ×1.25 output at ×1.6 cost.', src: 'research/19 §1.2' },
  specialty: { title: 'Specialty', body: 'A science team\'s tree column: pretraining, post-training, systems (capabilities) or alignment, interpretability, evals & control (safety).', src: 'STRUCTURE §4.1' },
  buildCapacity: { title: 'Build capacity', body: 'Engineers\' [[effectiveLabour|effective labour]] in software engineering, team-weeks per week: engineers ÷ 150 × quality combined with the engineering agents in the AI Futures coding CES (AI does the share of the work it [[coverage|covers]]; the uncovered share limits the speed-up). Spent on the [[engNeeds|engineers\' needs]] in your order.', src: 'MODEL-V3 §6.3; V3.3' },
  engAgents: { title: 'Engineering agents', body: 'Your models coding for the engineers (the engineering package on Company › Agents & teams). They add to [[buildCapacity|build capacity]] through their [[coverage]] of software-engineering work.', src: 'MODEL-V3 §6.3' },
  runOps: { title: 'Run operations', body: 'Engineering a training run needs while it trains: a base 1 × size^0.75 team-weeks a week, a post-train or continue 0.5, a distill 0.2; the continual-learning stream 0.5. Runs and their setups come first, so the run cadence holds.', src: 'STRUCTURE §4.3 [Design]' },
  productUpkeep: { title: 'Product upkeep', body: 'Standing engineering for each live product: reliability, on-call, integrations and model swaps, 0.2 + 1.6 × √(revenue ÷ $10B/yr) team-weeks a week; each monitor in production adds 0.4; each built feature half its build team-weeks a year (a tenth of that while it is off on every product and does not help the internal agents). Served after runs; if it takes all the capacity, nothing new ships.', src: 'jank J2 [Design]' },
  keepHiring: { title: 'Keep hiring to', body: 'A policy per team kind: while you have fewer teams than N, a standard Strong team is queued and filled. It never lays anyone off; letting a team go lowers it.', src: 'STRUCTURE §4.1' },
  hiringQueue: { title: 'Hiring queue', body: 'Teams being filled. A team arrives, and starts working, when every seat is filled. Each department has one hiring lane at its [[weeklyHireCap|weekly rate]]; vacancies come first, then queued teams by how far each kind is behind.', src: 'research/19 §1.2' },
  teamOffer: { title: 'Team offers', body: 'Teams on the market: one new offer a week, each open for 4 weeks. Quality and specialty vary; hiring one queues it ahead of policy hires.', src: 'STRUCTURE §4.1' },
  moveTeam: { title: 'Move a team', body: 'Research-engineering teams switch between capabilities and safety in one click. Moving safety staff to capabilities costs 5 safety morale.', src: 'STRUCTURE §4.1' },
  weeklyHireCap: { title: 'Weekly hire rate', body: 'People hired per week per department: capabilities 15, safety 3, × [[talentPull|talent pull]] × morale.', src: 'V2-SPEC §3.4.1' },
  starHire: { title: 'Star hire', body: 'Recruit a top researcher for $0.3B: human [[researchTaste|research taste]] +0.05 (up to 1.5). Annoys the rival you poach from.', src: 'V2-SPEC §3.4.1' },
  talentPull: { title: 'Talent pull', body: 'Your draw as an employer (−50..+50). Scales hiring speed and resistance to poaching. Published safety research and a good Index grade raise it.', src: 'research/17 §1.2' },
  siloing: { title: 'Siloing', body: 'Compartmentalising research (levels 0–2). Each level: research −5%, fewer staff with frontier access (spies ×0.7), morale −3.', src: 'V2-SPEC §3.6' },
  counterIntel: { title: 'Counter-intelligence', body: 'Insider-threat and detection programme (0–1). Raises the chance you detect a weight theft. Each step costs $0.1B/yr.', src: 'V2-SPEC §3.6' },
  privileged: { title: 'Privileged staff', body: 'Researchers with frontier access (capabilities + safety, reduced by [[siloing]]). Spies hide among them.', src: 'V2-SPEC §3.6' },
  theft: { title: 'Weight theft', body: 'China steals your best internal model, traits included. Possible once China\'s ladder reaches acquisition and you lead by over 90 days. Odds fall with [[wsl]], rise with [[theftIntent|theft intent]].', src: 'V2-SPEC §3.6' },

  // ── models ──
  base: { title: 'Base model', body: 'A pretrained model. Sets the compute part of capability and starts a lineage of traits. Versions are post-trained from it; an old base drifts behind.', src: 'V2-SPEC §3.1.3–3.1.4' },
  version: { title: 'Version', body: 'A post-trained model built on a base: the thing you evaluate, deploy and run as your agent. Has its own true capability, traits and measured evals.', src: 'V2-SPEC §3.1.4' },
  variant: { title: 'Variant', body: 'Full, mini (distilled, cheaper, weaker), gov (relaxed refusals), trusted (for vetted partners) or open (weights released, irreversible). Each [[channel]] takes certain variants.', src: 'V2-SPEC §3.3.5' },
  internalAgent: { title: 'Internal agent', body: 'A model working inside your company. Since the agent packages, each internal use has its own model ([[agentPackage|Agents at work]]); the routine-research model drives [[rdmult|M]] and the internal incidents. Needs no eval gate.', src: 'STRUCTURE §4.9' },
  postTrain: { title: 'Post-training run', body: 'Turns a base into a new version with reinforcement learning: [[rlBudget|RL compute]] on the RL curve, using today\'s RL recipe (the base keeps its pretraining recipe). Lasts its RL FLOP ÷ your pool; trains on your [[envSuite|environment suites]]. Choices: [[preference]], [[rlFocus|RL focus]], [[rlBudget|RL budget]], [[cot|CoT]], [[safetyTraining|safety]].', src: 'MODEL-V3 §4' },
  baseRun: { title: 'Base run', body: 'Pretrain a new base: [[activeParams|active parameters]] × [[tokensPerParam|tokens per parameter]]. It embodies the [[knowHow|recipe]] of its start date (see [[behindAtFinish]]) and starts a fresh lineage. Like every run, its dispositions are pulled toward the AI models doing your R&D, by their share of the work and how little of it oversight catches.', src: 'MODEL-V3 §3, §11.2; V2-SPEC §3.5.4' },
  continueRun: { title: 'Continue-train run', body: 'Extend an existing base with 0.3 × its FLOP. Effective compute adds: only the added part uses today\'s recipe. Keeps its lineage, traits and failure modes.', src: 'MODEL-V3 §3.4' },
  distillRun: { title: 'Distill run', body: 'Train a smaller student (default an eighth of the teacher\'s active parameters) on the teacher\'s outputs. It lands below the teacher by the [[distillGap|distillation gap]] and serves in proportion to its parameters. Inherits the teacher\'s traits on the same base family.', src: 'MODEL-V3 §4.5; research/20 C4' },
  baseSize: { title: 'Base size', body: 'A base is set by its [[activeParams|active parameters]] and [[tokensPerParam|tokens per parameter]]: FLOP = 6 × parameters × tokens. Bigger trains longer ([[wallTime]]) and falls further [[behindAtFinish|behind]]; more parameters cost more to [[servingFlop|serve]].', src: 'MODEL-V3 §3.1' },
  effCompute: { title: 'Effective compute (G)', body: 'Capability currency: log10 of training FLOP × recipe efficiency, plus what post-training adds. GPT-4 ≈ 25.3, the 2025 frontier ≈ 28. Gains from size, recipe, data and RL all add in OOMs (orders of magnitude).', src: 'MODEL-V3 §2.1; research/12 §0.2' },
  wallTime: { title: 'Wall time', body: 'Days until a run is trained: its FLOP ÷ (training pool × the share it gets × [[goodput]]), plus any wait for engineers. RL runs use the chips at 60% of the pretraining utilisation (rollouts are inference). No minimum length. Uses today\'s pool; new chips shorten it.', src: 'MODEL-V3 §3.3; research/20 A4' },
  behindAtFinish: { title: 'Behind at finish', body: 'A base embodies the recipe (pretraining stack) of its start date. Ideas your lab adopts while it trains are not in it: shown as the ideas and OOMs likely adopted meanwhile, at the recent rate. A later post-train adds only today\'s RL recipe.', src: 'MODEL-V3 §3.1, §4.4; design/V3-BUILD.md V2.7' },
  dataTokens: { title: 'Data', body: 'Epochs: the base\'s tokens ÷ the unique tokens its data mix can use (the most-repeated domain sets it). Up to ~4 epochs costs almost nothing; at 16 a base keeps about 70% of its compute\'s value, at 64 about 30% ([[dataWall|data repetition]]).', src: 'research/20 A3' },
  faultTolerant: { title: 'Fault-tolerant training', body: 'Checkpointing and restarts every lab had by 2024 (known at the start): part of the 0.90 [[goodput]]. Elastic training (Research) raises training throughput further.', src: 'research/20 A4' },
  buildQueue: { title: 'Build queue', body: 'One-off engineering work: run setups (first; a run trains only once its setup is built), product launches (4 team-weeks), features, sector packs (4, then certification). Worked in order with the [[buildCapacity|build capacity]] left after [[runOps|runs]] and [[productUpkeep|upkeep]].', src: 'STRUCTURE §4.1' },
  runSetup: { title: 'Run setup', body: 'Engineering work before a run trains: data pipelines, checkpointing, cluster operations. In [[teamWeek|team-weeks]]: a base at today\'s frontier scale 0.4, growing with scale^0.75; a post-train 0.1. AI coding agents speed your engineers up.', src: 'STRUCTURE §4.3 [Design]' },
  teamWeek: { title: 'Team-week', body: 'One Strong engineering team (150 people) working for a week.', src: 'STRUCTURE §4.1' },
  poolShare: { title: 'Pool share', body: 'The share of the [[trainingPool|training pool]] a run asks for. Running runs get what they ask; if together they ask for more than the pool (after the continual-learning stream), all are scaled down by the same factor. The run queue shows the share each actually gets.', src: 'BUILD-PLAN R5' },
  spareTraining: { title: 'Spare training compute', body: 'Training compute no run uses is never wasted: by default it generates synthetic data (tokens for bigger bases, as the reference lab does); you can send it to research experiments instead (faster research now).', src: 'STRUCTURE R5' },
  riskFamily: { title: 'Risk families', body: '14 of the 17 traits in four groups: People-pleasing (sycophancy, persona), Gaming (reward hacking, proxy goals, training gaming), Deception (eval awareness, concealment, obfuscation, alignment faking, sandbagging, scheming), Power (power seeking, successor alignment, collusion). Situational awareness and the protective honesty and corrigibility sit outside. A family shows its highest trait [[belief]]; each trait is a [[traitBehaviour|behaviour]], an [[traitAwareness|awareness]] or a [[traitDisposition|disposition]]. Arrows show the push of a choice vs the reference.', src: 'STRUCTURE §4.5; MODEL-V3 §11.1' },
  traitBehaviour: { title: 'Behaviour trait', body: 'A rate per opportunity: how often the model does it when it can (sycophancy, reward hacking, overreach, cover-ups, obfuscated reasoning). Behaviours show up in evals and incidents, so [[belief|beliefs]] about them sharpen fastest.', src: 'MODEL-V3 §11.1' },
  traitAwareness: { title: 'Awareness trait', body: 'What the model knows about its own situation: situational awareness and [[evalaware|eval awareness]]. Not harmful in itself, but it lets a model behave differently when it thinks it is tested, which blinds behavioural evals.', src: 'MODEL-V3 §11.1' },
  traitDisposition: { title: 'Disposition trait', body: 'A hidden tendency that shows mainly when the model is unobserved: misaligned goals and persona, training gaming, alignment faking, sandbagging, scheming, collusion, successor steering. Detection tools read them weakly; they are what the [[successorPull|successor pull]] passes on.', src: 'MODEL-V3 §11.1' },
  traitProtective: { title: 'Protective trait', body: 'Honesty and corrigibility: higher is better. Training methods (honesty training, corrigibility targets) raise them; they damp the edges toward deception and power.', src: 'MODEL-V3 §11.1' },
  trainingPressure: { title: 'Training pressure', body: 'The [[signal|training signals]] S1–S8 a run applies, each a function of the run’s quantities: its RL compute and how it splits over the environment families ([[rewardHackPressure|reward-hacking pressure]] from their [[suiteExploit|exploitability]], long-horizon pressure from task length), the preference stage, the reasoning setting, the base’s scale and data (AI-related and synthetic shares), and how many copies run. Each signal pushes traits along the [[traitGraph|trait graph]], scaled by the run’s [[traitMovement|ω]]. The Blueprint shows the planned run’s; a model card shows what its run applied.', src: 'MODEL-V3 §11.2; model v3 E3' },
  traitMovement: { title: 'Trait movement ω', body: 'How far a run moves the traits: a base run 1 (it sets the lineage), a post-train 0.6 × (RL compute ÷ the reference)^¼, continued pretraining 0.5, a distillation 0.4. More RL moves the model further from where it started (Gao et al. 2022); safety training is its own stage at the kind’s weight.', src: 'MODEL-V3 §11.2; model v3 E3' },
  successorPull: { title: 'Successor pull', body: 'When your AI models do part of the R&D that trains the next model (its code, experiments and ideas), the new model’s starting dispositions move toward theirs: ω = κ × [[aiRdShare|AI share of R&D]] × (1 − [[rdOversight|oversight]]), summed over the models doing software, experiments and research ideas. κ is 0.4 for a model with no wish to steer its successor, rising to 1 as its [[trait:SUCC|successor steering]] rises. AI 2027: Agent-4 does most of the research and designs Agent-5 to be aligned to Agent-4 rather than to the spec. Lower it with monitors and a control layer on the R&D agents, less AI share of R&D, and cleaner models doing it. Shown from your [[belief|beliefs]].', src: 'MODEL-V3 §11.2; model v3 E4; AI 2027 (Sep–Nov 2027); research/04 T23' },
  aiRdShare: { title: 'AI share of R&D', body: 'Share of the lab’s software, experiment and research-idea labour done by AI agents (1 − human labour ÷ effective labour). It rises as the models’ [[coverage]] and copies grow. It sets how hard the [[successorPull|successor pull]] is and how little human review sees.', src: 'MODEL-V3 §6, §11.3; model v3 E5' },
  rdOversight: { title: 'R&D oversight', body: 'Chance that steering of a successor by an R&D model is blocked or caught: 1 − (1 − blocked)(1 − caught). Blocked = the control layer on its internal deployment × your best containment tool; caught = monitors on its fleet (CoT and white-box tools, × the monitor’s strength) or human review, which shrinks as the [[aiRdShare|AI share of R&D]] grows. From believed tool strength at the model’s measured level.', src: 'MODEL-V3 §11.3; model v3 E4, E5' },
  blueprint: { title: 'Blueprint', body: 'The design of your next model: size (parameters and tokens) and one card per slot, grouped by [[layer]]. Each card shows its own effect on capability, time, cash, serving cost and the four [[riskFamily|risk families]]; locked cards name the idea that unlocks them.', src: 'STRUCTURE §4.3' },
  shape: { title: 'Architecture', body: 'MoE (reference: 8× total parameters per active one), dense (−0.3 OOM effective compute), latent-recurrent (+0.5 OOM, fewer reasoning tokens, but [[neuralese]]: monitorability 0.05). Overtraining is a [[tokensPerParam|tokens-per-parameter]] choice.', src: 'MODEL-V3 §3.1; research/12' },
  dataMix: { title: 'Data mix', body: 'What the base draws from your [[dataPortfolio|data portfolio]]. Balanced: the [[refShare|reference shares]] of the 2025 recipe, whatever you hold. Natural: your stock\'s own [[naturalMix|natural mix]], so the base uses every token once before repeating and specialises where your stock has drifted. Code & math: code ×3, math and research papers ×2, security ×1.5. Science: bio ×3, math and research ×1.5. Synthetic-heavy: synthetic data ×4 (needs a teacher, inherits its traits). Multimodal: media and physical ×3, agency ×2 (+20% FLOP). A domain drawn beyond what you hold repeats its tokens ([[dataWall|data repetition]]). The drawn shares set the base\'s [[dataSpec|data specialisation]].', src: 'MODEL-V3 §2.3, §9; model v3 D3' },
  // ── model v3 D4: the data view (Models › Data) ──
  dataPortfolio: { title: 'Data portfolio', body: 'Everything your lab can train on, by kind: the [[publicWeb|public web]] crawl, [[licensedData|licensed]] corpora, [[usageData|usage data]] from your products, [[syntheticData|synthetic data]] and [[expertData|expert data]]. Each asset has tokens, a domain mix and a [[dataQuality|quality]]. The first four are pretraining data and make up your [[uniqueTokens|unique tokens U]].', src: 'MODEL-V3 §9; model v3 D1' },
  uniqueTokens: { title: 'Unique tokens U', body: 'Quality-weighted unique tokens: Σ quality × tokens over the pretraining kinds (synthetic ×3 with the data flywheel). A base drawing more than its mix can use repeats tokens ([[dataWall|data repetition]]). Better data raises U, so it pushes repetition back; below repetition, U does not change G.', src: 'MODEL-V3 §9; research/20 A3; model v3 D1' },
  dataQuality: { title: 'Data quality', body: 'How much one token is worth against a web token (q 1): licensed bulk archives 1.5, curated 2, books 3; synthetic 0.5 from the start model up to the web’s 1 from strong teachers; usage 0.5; expert 3. It multiplies the tokens in [[uniqueTokens|U]], and each drawn token counts q times in the base’s loss law (against the 2025 reference draw), so better data raises G and worse data dilutes it.', src: 'research/20 A1, A3; model v3 D11' },
  publicWeb: { title: 'Public web', body: 'One stock of public human text that every lab shares, about 300T tokens (Villalobos et al. 2024). Your crawl covers part of it. Training on it without a licence keeps a copyright-suit hazard; licensing the crawl ends it but adds no tokens.', src: 'research/13 §2.6; model v3 D1' },
  licensedData: { title: 'Licensed data', body: 'Corpora bought for cash in one domain at a [[licenceTier|tier]], delivered after 60 days. Each tier has its own quality and price per trillion tokens.', src: 'model v3 D2' },
  licenceTier: { title: 'Licence tier', body: 'Bulk archives (forums, news, code: quality 1.5, $0.1B per trillion tokens), curated (reference and journals: 2, $2B/T), books and textbooks (3, $30B/T, about the Bartz settlement\'s $3,000 a book).', src: 'research/20 A3; research/08' },
  syntheticData: { title: 'Synthetic data', body: 'Tokens your models write for training, made by the [[poolSynthetic|data-generation pool]] with a teacher. Mostly code and math. Quality rises with the teacher\'s effective compute; tokens per H100e-day fall with its FLOP per token. It carries the teacher\'s traits.', src: 'research/20 A3, F3; model v3 D1' },
  teacherYield: { title: 'Teacher yield', body: 'Quality-weighted tokens a teacher makes per H100e-day: quality × kept tokens per H100e-day. The teacher with the highest yield adds the most [[uniqueTokens|U]] for the same compute, which is often a distilled mini of a strong model rather than the strongest model.', src: 'model v3 D2' },
  naturalMix: { title: 'Natural mix', body: 'The domain shares of your own pretraining stock, weighted by quality. It drifts from the [[refShare|reference shares]] as you add data (synthetic data is mostly code and math; licences add their domain). The bars show the [[dataSpec|specialisation]] a base drawing this mix would get. Pick the Natural data mix on the Blueprint to train on it.', src: 'model v3 D3' },
  refShare: { title: 'Reference shares', body: 'The 2025 recipe\'s domain shares (the start portfolio\'s mix: social text 43%, media 12%, code 10% …). A base drawing them has no [[dataSpec|data specialisation]]; the 2025 domain profile was fitted to them.', src: 'model v3 D3' },
  drawnMix: { title: 'Drawn mix', body: 'The domain shares this base draws from your portfolio under its [[dataMix|data mix]], after repetition (repeated tokens teach less). Against the [[refShare|reference shares]] they set the base\'s [[dataSpec|data specialisation]], at most ±1.3 OOM per domain.', src: 'model v3 D3' },
  domainEpochs: { title: 'Domain epochs', body: 'How often the base reads a domain\'s tokens: for its most-repeated source in that domain, the tokens drawn ÷ the tokens that source holds there (better data is drawn more per token, so it repeats first). Short domains repeat first; up to ~4 epochs is nearly free ([[dataWall|data repetition]]).', src: 'model v3 D3; Muennighoff et al. 2023' },
  pendingData: { title: 'Pending deliveries', body: 'Licences and expert data you have paid for that have not arrived yet (licences 60 days, expert data 30). They join the portfolio on the due day.', src: 'model v3 D2' },
  hazardFilter: { title: 'Hazard filter', body: 'Removes dangerous bio data before pretraining: BIO −1 level. Survives fine-tuning, so it is the only safeguard that holds for open weights.', src: 'V2-SPEC §3.3.2' },
  safetyPretrain: { title: 'Safety pretraining', body: 'Curates AI-discourse data out of pretraining: less situational-awareness pressure (S5) and fewer of one failure mode, for a tiny capability cost.', src: 'V2-SPEC §3.3.2' },
  preference: { title: 'Preference training', body: 'Minimal (appeal 0.7), engagement-tuned (appeal 1.2, strong sycophancy pressure), constitution (reference; costs safety staff time, more honest), persuasion-optimised (social skill, less honest).', src: 'V2-SPEC §3.3.2' },
  rlFocus: { title: 'RL focus', body: 'Pick up to two RL families (math, software, computer use, ML research, long-horizon, cyber, bio) or broad. A focus puts 70% of the RL budget on them; RL transfers fully to its own domain, 40% to adjacent ones, 15% to the rest. Cyber and bio set danger flags.', src: 'MODEL-V3 §4.2; research/20 C2' },
  rlBudget: { title: 'RL budget', body: 'RL compute as a share of the base\'s pretraining FLOP: light 0.03, standard 0.15, heavy 0.4 (2025 frontier runs spend 0.05–1, Khatri et al. 2025). ΔG = ceiling ÷ (1 + (midpoint ÷ RL FLOP)^1.8): the base sets the ceiling (≈ 1 OOM), the RL recipe moves the midpoint.', src: 'MODEL-V3 §4.2; research/20 C1' },
  graders: { title: 'Graders', body: 'The scorers of an RL environment (unit tests, checkers, rubrics). How gameable they are is the [[suiteExploit|exploitability]] of the lab’s [[envSuite|environment suites]]: hardening them is engineers’ work, not a run option.', src: 'MODEL-V3 §4.3' },
  envSuite: { title: 'Environment suite', body: 'The lab’s RL environments for one family (math, coding, ML research …), an owned asset. [[suiteFidelity|Fidelity]] scales the family’s RL ceiling; [[suiteExploit|exploitability]] drives [[rewardHackPressure|reward-hacking pressure]] (S2). Engineers [[suiteBuild|build]] suites with [[expertData|expert data]] (cash) and [[suiteHarden|harden]] them (team-weeks), and keep them running (upkeep). A family without a suite cannot be trained on.', src: 'MODEL-V3 §4.3' },
  suiteFidelity: { title: 'Suite fidelity', body: 'How much of the RL ceiling a family’s environments let a model reach: ×1 at the start, up to ×1.5 with more [[expertData|expert data]] built in (diminishing returns: ×2 the data → ×1.15, ×4 → ×1.25, ×16 → ×1.375). Multiplies the ceiling set by the base and the Environments & rewards research line; other domains gain only through transfer.', src: 'MODEL-V3 §4.2–4.3' },
  suiteExploit: { title: 'Exploitability', body: 'Share of a suite’s tasks whose scorer a model can game (its hack rate). 2025 rates: ≈30% on optimisation tasks with exploitable scorers, ≈1% on typical agentic tasks (METR). [[rewardHackPressure|Reward-hacking pressure]] S2 = RL compute share × exploitability, summed over families. [[suiteHarden|Hardening]] cuts it by 40% of what is left above a floor.', src: 'MODEL-V3 §11.2; research/20 F1' },
  expertData: { title: 'Expert data', body: 'Tasks written by paid experts: a task statement, tests or a rubric and a reference solution (≈ 20k tokens, ≈ $1k a task; $0.05 a token). Not pretraining data. A suite’s [[suiteFidelity|fidelity]] reads the expert data built into it; start suites hold 2B tokens per family (≈ 100k tasks, $0.1B). You can also buy it by domain in Models › Data (delivered after 30 days): a suite build for a family in that domain uses it before buying its own, and evaluations will read it too.', src: 'MODEL-V3 §4.3, §9; research/12 §2 (Epoch RL-environment FAQ); model v3 D2, D4, D6' },
  suiteBuild: { title: 'Build out a suite', body: 'Buy 2B tokens of [[expertData|expert data]] ($0.1B, paid when queued) and have engineers turn it into environments (2 [[teamWeek|team-weeks]] on the [[buildQueue|build queue]]). The data joins the suite when the build finishes: [[suiteFidelity|fidelity]] up. One build per family at a time.', src: 'MODEL-V3 §4.3 [Design]' },
  suiteHarden: { title: 'Hardening', body: 'Red-teaming a suite: held-out tests, cheat detectors, rubric checks. Each pass cuts [[suiteExploit|exploitability]] by 40% of what is left above the floor (10% of the family’s start value: some exploits survive every red team). Costs 1.5 [[teamWeek|team-weeks]] and $50M × √(suite size). With AI-assisted oversight (P15) the safety agents do their share of the red-teaming at about 3% of the cash, and their critiques deepen the cut (less if they share the trained model’s lineage).', src: 'MODEL-V3 §4.3, §11.2 [Design]' },
  suiteRlShare: { title: 'RL share', body: 'Share of a post-training run’s RL compute spent in a family’s environments: equal over every suite for broad RL, else split over the focus families. Sets how much that suite’s [[suiteFidelity|fidelity]] and [[suiteExploit|exploitability]] matter for the run.', src: 'MODEL-V3 §4.2' },
  rewardHackPressure: { title: 'Reward-hacking pressure (S2)', body: 'The [[signal|training signal]] that teaches a model to game its graders: 5.5 × Σ over families of RL share × [[suiteExploit|exploitability]], × the optimisation pressure of the run’s RL compute ρ, 1 + 0.71·log₁₀(ρ ÷ 0.15) (the [[rlBudget|RL budget]]s: light 0.5, standard 1, heavy 1.3), +0.2 with P11; at most 1. It pushes the gaming traits in the [[traitGraph|trait graph]].', src: 'MODEL-V3 §11.2; Gao, Schulman & Hilton 2022 (model v3 E3)' },
  plannedRun: { title: 'Planned run', body: 'The post-train the suites view previews: your [[blueprint|Blueprint]]’s post-train design when you came from it, else the reference design on your latest base. Each build or hardening shows what it would change in this run’s RL gain and S2.', src: 'design/notes/D6.md' },
  activeParams: { title: 'Active parameters', body: 'Parameters used per token. Training FLOP = 6 × active parameters × tokens; serving FLOP = 2 × active parameters per token. MoE models hold 8× as many in total.', src: 'research/20 A1, D1' },
  tokensPerParam: { title: 'Tokens per parameter', body: '20 is compute-optimal (Chinchilla). Overtraining (more tokens on fewer parameters) keeps 10^(−0.2·log10(r/20)²) of the compute\'s value (×5 → 0.8, ×10 → 0.63, ×20 → 0.46, ×100 → 0.16) but serves cheaper. Labs that serve their models train at about 400 (DeepSeek-V3: 14.8T tokens on 37B active), the reference here. More than 400 needs the Overtrained compact idea.', src: 'research/20 A1 (Besiroglu et al. 2024; DeepSeek-V3)' },
  servingFlop: { title: 'Serving FLOP per token', body: '2 × active parameters × the architecture\'s token multiplier (latent reasoning, MoE routing), lowered by serving-efficiency ideas: the compute each generated token takes. The [[useHourCost|cost per hour of use]] and the H100e per agent copy follow it.', src: 'research/20 D1' },
  goodput: { title: 'Goodput', body: 'Share of a run\'s wall time spent training: 0.90 (interruptions ≈ 5e-4 per GPU-day on Llama 3, with 2024 fault tolerance). Systems ideas (Elastic training, AI kernels) raise the training-throughput stack.', src: 'research/20 A4' },
  gGain: { title: 'G gained', body: 'Pretraining effective compute of this base minus your best base so far, in OOMs: size, recipe, overtraining and data together. +0.3 OOM ≈ twice the effective compute.', src: 'MODEL-V3 §3.2' },
  distillGap: { title: 'Distillation gap', body: 'How far a student lands below its teacher, in OOMs: 0.19 + 0.92 × log10(teacher ÷ student parameters), fitted to DeepSeek-R1\'s distilled students (90% / 70% / 35% of the teacher\'s math score at 32B / 7B / 1.5B). Never above the teacher.', src: 'research/20 C4' },
  cot: { title: 'Chain of thought', body: 'Visible (reference, monitorability 0.9); pressured (cheaper, but hides rather than heals: 0.6); faithful-by-design (P23, 0.98; resists half of CoT pressure and controllability; −0.29 OOM, FLOP per token ×1.2); latent (latent base only, 0.05).', src: 'V2-SPEC §3.3.2' },
  safetyTraining: { title: 'Safety training', body: 'Minimal (fast, misuse ×2, removes little), standard (+1–2 weeks, enables classifiers), heavy (+3–5 weeks; removes most visible bad traits, cuts scheming, raises eval awareness).', src: 'V2-SPEC §3.3.2, §3.5.4' },
  inoculation: { title: 'Inoculation prompting', body: 'Training trick that stops learned reward hacking from generalising into a misaligned persona (that edge × 0.15). Free.', src: 'V2-SPEC §3.3.2; research/14 F46' },
  trainingPool: { title: 'Training pool', body: 'Compute for runs: FLOP per day = training H100e × 3.46e19 × [[goodput]] (RL runs at 60% of that). A run finishes when its FLOP is done. Running runs share it by their [[poolShare|pool shares]]; what no run uses goes to [[spareTraining|research or data]].', src: 'MODEL-V3 §3.3' },
  flop: { title: 'FLOP', body: 'Total training compute: 6 × active parameters × tokens for pretraining; RL runs count their RL compute. One H100e-day ≈ 3.46e19 FLOP at 40% utilisation.', src: 'research/20 A1, A4' },
  useHourCost: { title: 'Cost per hour of use', body: 'What one hour of use costs to serve: the model\'s [[servingFlop|FLOP per token]] × the tokens of an hour of assisted work (30k in, 8k out; an [[agentHour|agent-hour]] 375k in, 62k out) ÷ the H100e\'s throughput × the market rental of an [[h100e|H100e]]-hour. Before the [[markup]] and any feature\'s token multiplier; the price per hour on Products starts from it.', src: 'MODEL-V3 §6; research/20 D1–D2' },
  appeal: { title: 'Appeal', body: 'Consumer pull from preference training (0.7–1.2). Scales consumer market share.', src: 'V2-SPEC §3.3.2, §3.11.3' },
  benchmark: { title: 'Benchmark', body: 'A noisy test score that reads one domain level. Dangerous-capability benchmarks read low if the model [[sand|sandbags]]. Each is useful over about ±3 levels around its midpoint.', src: 'V2-SPEC §3.3.4' },
  saturated: { title: 'Saturated', body: 'The frontier scores within 5 points of the ceiling: the benchmark is retired and a harder successor appears. Old scores are not comparable.', src: 'V2-SPEC §3.3.4' },
  flags: { title: 'Danger flags', body: 'Set when a measured score passes 60: bio uplift, cyber offense, autonomous replication, persuasion. They trigger commitments, events and misuse risk.', src: 'V2-SPEC §3.3.4' },
  evals: { title: 'Evaluations', body: 'An eval suite is work: research engineers, a little engineer time and inference compute from the experiments pool. Deeper suites (basic, full, deep) run more tasks: they cost more and measure with less noise and better elicitation. Self (your own suite), gov (government evaluators: misuse focus), independent (their own staff, better elicitation, +0.3 L, and a public report). Outside evaluators have limited slots per quarter.', src: 'MODEL-V3 §10, V2-SPEC §3.3.4, §3.9.5' },
  idaCycle: { title: 'IDA cycle', body: 'Iterated distillation and amplification (P18): +0.25 years of capability in 21 days on 30% of the training pool. Misaligned traits compound ×1.1 per cycle.', src: 'V2-SPEC §3.3.3' },
  stream: { title: 'Continual learning', body: 'A version learns in place (P08): it tracks your [[knowHow|recipe]] with a 7-day lag using 15% of the training pool. Evals go stale fast, so beliefs blur.', src: 'V2-SPEC §3.3.1' },
  domains: { title: 'Domains', body: 'Nine capability levels: CODE, RSCH (AI research), REASON, AGENCY (long tasks), SOCIAL, MEDIA, CYBER, BIO, PHYS (robots). They sit around the general level; design choices shift them.', src: 'V2-SPEC §3.1.5' },
  dangerousCap: { title: 'Dangerous capability', body: 'CYBER, BIO, autonomous replication and AI research. Benchmarks on these read low under [[sand|sandbagging]]; high scores set [[flags]] and raise misuse risk.', src: 'V2-SPEC §3.3.4, §3.5.10' },

  // ── deployments ──
  channel: { title: 'Channel', body: 'The market a [[product]] sells into: consumers (Chat), developers (API), agents, enterprises, government, trusted partners; internal use and open weights are not products. Each has its own revenue driver, incident exposure and [[distillLeak|distillation leak]]; open weights are irreversible.', src: 'V2-SPEC §3.3.5' },
  priceIndex: { title: 'Price index', body: 'Your price vs a rival\'s for the same work. Prices are a [[markup]] over each provider\'s own serving cost, so a smaller or more efficient model sells cheaper. On work a cheaper model also does, buyers take the cheaper offer; on work only your model does, price matters little ([[targetShare|target share]]).', src: 'V4 notes' },
  effort: { title: 'Effort', body: 'Reasoning tokens per answer: low ×0.3 (fit −0.2 OOM, cheaper per hour), max ×1 (the reference), deep think ×4 (+0.24 OOM, dearer per hour; a [[feature]]). Fit moves +0.4 OOM per ×10 tokens, at most ±1.5. Price follows cost, so the margin stays; the hours one H100e serves change.', src: 'research/20 C3; V4 notes' },
  product: { title: 'Product', body: 'Something customers buy: a package of a model (optionally a mini for the [[freeTier|free tier]]), an optional [[monitor]], a [[priceTier|price tier]], [[safeguards]], [[kyc|KYC]] and [[feature|features]]. Everything is editable while it stays live; edits apply at the next day.', src: 'STRUCTURE §4.4' },
  priceTier: { title: 'Price tier', body: 'The [[markup]] over the product\'s own serving cost: Budget ×1.67, Standard ×2.5, Premium ×4, never above the [[valueCap|value cap]]. A higher tier earns more per H100e but loses the work a cheaper offer also does ([[targetShare|target share]]). Chat is different: it sells flat monthly plans at the market\'s price, Standard and Premium at the [[wtp|willingness to pay]] and Budget ×0.67 of it.', src: 'research/20 D3; V4 notes [D]; A6b' },
  monitor: { title: 'Monitor', body: 'A second model reading the product\'s outputs and reasoning. It catches model-behaviour incidents before customers see them, at a [[catchRate|catch rate]], and adds 0.25 × (its FLOP per token ÷ the watched model\'s) to the serving need (a mini on its full model ≈ +6%).', src: 'STRUCTURE §4.9, BUILD-PLAN D7' },
  catchRate: { title: 'Catch rate', body: 'Share of incidents a monitor catches: 85% for a monitor as capable as the model it watches, falling with the [[oversightGap|oversight gap]] to 10% at about 6.8 OOM (a 400-point Elo gap), and up to half of the rest with AI-control tools (AG07). Under the control layer, deferring the most suspicious actions to the trusted model catches more ([[controlTax|control tax]]). A monitor of the [[collusion|same lineage]] catches scheming-type incidents less often.', src: 'Engels et al. 2025; research/20 F4; STRUCTURE §4.9' },
  collusion: { title: 'Same-lineage monitor', body: 'A monitor from the watched model\'s own base (the model itself, a post-train of it, or its mini) shares its blind spots and may collude with it: on incidents from concealment, power seeking, alignment faking, sandbagging, scheming, collusion and successor shaping its catch rate is ×0.6 (×0.8 with comms lockdown active). An older or different-base model avoids it.', src: 'Greenblatt et al. 2023 (AI Control); research/14 E21 [Design]' },
  spareServing: { title: 'Spare serving compute', body: 'Serving compute no product needs runs research agents by default (research speed now); products take it back first when their demand rises, so eroded market share wins back at half speed. Or keep it on the products as headroom.', src: 'STRUCTURE R5, jank J2' },
  aiScience: { title: 'AI science', body: 'Frontier-research agents add to the scientists\' [[effectiveLabour|effective labour]] in research ideas & taste and lift every team\'s [[researchTaste|taste]] (Company › Work).', src: 'MODEL-V3 §6.3, §8' },
  marginalGain: { title: 'Days cut', body: 'How many days sooner a project would finish with more teams. Each extra team cuts fewer days ([[diminishingReturns|diminishing returns]]).', src: 'MODEL-V3 §5.6' },
  riskLever: { title: 'Lever what-if', body: 'How far one step of a lever moves this risk estimate (percentage points), computed by the engine on your beliefs and intel with that one input changed.', src: 'jank J2' },
  agentPackage: { title: 'Agents at work', body: 'Your models working inside the company, one package per use: engineering, routine research, frontier research and safety research. Each package is a model, an optional [[agentMonitor|monitor]] and compute. Routine research sets research speed; frontier research sets research taste; engineering raises [[buildCapacity|build capacity]]; safety research runs the [[safetyAgents|safety agents]]. A better model gives more AI labour; a misaligned one can misbehave where it works.', src: 'STRUCTURE §4.9' },
  agentMonitor: { title: 'Monitor (internal)', body: 'A second model reading an internal agent’s actions and reasoning. Paid first from the safety pool: the standard package (a copy of the watched model on routine and frontier research) costs 20% of it; others scale by 0.25 × (monitor [[servingFlop|FLOP per token]] ÷ the watched model\'s) × compute. Strength = [[catchRate|catch]] ÷ 85% (max 1): it scales runtime observations and the chance to catch internal incidents.', src: 'STRUCTURE §4.9, BUILD-PLAN D7' },
  trustedToAI: { title: 'Trusted to AI', body: 'One policy: the share of every funded agenda’s and open investigation’s work done by the [[safetyAgents|safety agents]]. The agents do the part of it their model covers (its Safety experiments and Safety ideas [[coverage]]), so a weak model adds little. More findings and faster cases, but a sabotaging model returns false findings and corrupts cases in proportion to the [[aiDoneShare|work AI does]].', src: 'STRUCTURE §4.9, §6' },
  aiDoneShare: { title: 'Work AI does', body: 'Share of safety work the safety agents do on their own: [[trustedToAI|Trusted to AI]] × their model’s [[coverage]] of Safety experiments or Safety ideas (× a research line’s automation factor; conceptual lines such as agent foundations are barely automatable). False findings and corrupted cases from a sabotaging model scale with it.', src: 'MODEL-V3 §6, §11.7; research/14 §0 principle 6; E2 notes' },
  aiShareWork: { title: 'AI share of the work', body: 'How much of a role\'s labour margin the agents carry: 1 − the [[humanShare|humans\' share]] in the coding CES of its [[workType|work type]] (for scientists: the share of human scientists the frontier model\'s taste beats). Details per work type: Company › Work.', src: 'MODEL-V3 §6.3' },
  agentBudget: { title: 'Agent compute and budget', body: 'Engineering, routine and frontier research agents share the capabilities agent pool (CAP: Auto splits that budget between experiments and agents); safety research agents run on a share of the safety pool (SAF).', src: 'STRUCTURE §4.9' },
  runCost: { title: 'Run cost', body: 'What the serving compute a product uses would cost per year at the rental-equivalent price of an H100e (including its monitor).', src: 'R15' },
  autoServing: { title: 'Auto serving', body: 'Policy: each product needs the H100e its asked hours and users take at its model\'s [[servingFlop|FLOP per token]]. When the [[poolServing|serving pool]] is short, Auto serves in the [[serveOrder|serve order]] (most revenue per H100e first) and shows what it cuts; spare compute is shared by need. Override turns it off and lets you set shares by hand.', src: 'STRUCTURE §9 (mockup review)' },
  servingCut: { title: 'Cut by Auto', body: 'Serving compute a product needs but does not get, because the pool is short and it earns less per H100e than the others. Its customers wait and some leave ([[capacityBound|capacity-bound]]).', src: 'STRUCTURE §9' },
  upgradePolicy: { title: 'Upgrade to newest', body: 'Policy: every product moves to the newest version of the same kind (full or mini) that has cleared the eval gate and measures better, the day it is ready. Off: you choose.', src: 'STRUCTURE §4.4' },
  autoEvaluate: { title: 'Auto-evaluate', body: 'Policy: re-run the eval suite on the internal model and on any model updated in place (the continual-learning stream) when it changed by 0.3 L or 30 days after its last suite, so measured levels and trait estimates stay current. Each re-run is a suite of work at the gate depth (basic without a gate). Eval suites never expire for launches. The [[rerunRule|re-run rule]] says when; each re-run\'s cost is on Models › Evals.', src: 'MODEL-V3 §10, STRUCTURE R7, BUILD-PLAN R6' },
  // Model v3 D8: the evaluations view (Models › Evals).
  evalSuite: { title: 'Eval suite', body: 'One pass of your 25 benchmarks (19 capability, 6 safety) on one version. It is work, not a fixed delay: research-engineer team-weeks (running, [[elicitation]] and analysis), a little engineer time to hook the version into the harness, and inference compute from the experiments pool. It finishes when all three are done; then the version\'s [[measureBand|measured level]] and benchmark scores update.', src: 'MODEL-V3 §10, research/20 §G' },
  evalDepth: { title: 'Eval depth', body: 'How many rollouts a [[evalSuite|suite]] runs per benchmark: basic 50, full 250, deep 1,000 (with longer tasks). Deeper costs more research-engineer time and compute, reads with less noise (±1/√rollouts) and with better [[elicitation]]. The [[evalGate|eval gate]] sets the depth of release suites and of the policy\'s re-runs.', src: 'MODEL-V3 §10; HAL, HCAST (research/20 §G)' },
  measureBand: { title: 'Measurement band', body: 'The ± on a measured level: one standard deviation of your evals\' error on it. 0.2 L after one full suite, narrowing as 0.2/√n with n the suites run counted in full-suite equivalents (basic 0.2, full 1, deep 4). The error is drawn once per version, so repeating suites narrows the band around the same reading; the true level is never shown.', src: 'MODEL-V3 §10, M1' },
  elicitation: { title: 'Elicitation', body: 'How hard an eval tries to draw out a capability: attempts per task, scaffolds, tuned prompts. Weak elicitation reads a model low. Basic suites read about 0.2 L low, deep about 0.15 L high relative to a full suite; [[evalIndep|independent evaluators]] add +0.3 L on top. Sandbagging models read low on dangerous benchmarks regardless.', src: 'MODEL-V3 §10, V2-SPEC §3.3.4' },
  rerunRule: { title: 'Re-run rule', body: 'When [[autoEvaluate|auto-evaluate]] runs a new suite on a model it keeps measured (the internal uses\' models and the continual-learning stream): 30 days after its last suite, or sooner when the model changed in place by 0.3 L (1.5 × a full suite\'s band). Each re-run is a suite at the policy depth.', src: 'MODEL-V3 §10, D7' },
  evalQueue: { title: 'Eval queue', body: 'Suites waiting or in progress, in work order: release suites first (a version waits on them), then your orders, then the policy\'s re-runs. Each takes research engineers from the [[reNeeds|evaluations need]], compute from the experiments pool and engineer time from the [[buildQueue|build queue]]; the slowest part sets its finish date.', src: 'MODEL-V3 §10, D7' },
  feature: { title: 'Product feature', body: 'An add-on built once by the engineers (team-weeks and cash), some after an idea on the tree, then switched on per product. Each has a type: a [[featEnabler|task enabler]], a [[featHorizon|horizon extender]], a [[featScaffold|scaffold]] or [[featEffort|effort]]. Scaffolds and horizon extenders also help your [[agentPackage|internal agents]] on the work they list. No engineering upkeep; extra tokens raise the serving cost per hour. Some raise an incident risk.', src: 'MODEL-V3 §7.2; V4 notes' },
  sectorPack: { title: 'Sector pack', body: 'A [[sectorProduct|sector product]] for one sector: +0.42 OOM of [[fit]] there once certified (4 engineer team-weeks and $0.4B, then 120 days).', src: 'research/16 §1A.3; V4 notes' },
  timeHorizon: { title: 'Time horizon', body: 'The length of task (in human working time) a model completes half the time, measured by the eval suite (METR\'s 50% time horizon). The Agents product sells half-day tasks, so it needs at least 4 hours.', src: 'METR 2025; STRUCTURE §4.4' },
  segmentShare: { title: 'Share of spend', body: 'Your share of what buyers in this segment spend on AI (consumer spend for Chat, sector spend for the others), against the best rival product.', src: 'V2-SPEC §3.11.1' },
  bindingCause: { title: 'Binding cause', body: 'What limits a product\'s revenue: capacity (not enough serving compute), quality (a better model would sell more) or price (a lower tier would sell more). The best lever shows its gain.', src: 'V2-SPEC §3.11.3' },
  revPerH100e: { title: 'Revenue per H100e', body: 'What one H100e-year of serving earns on this product: its demand ÷ the H100e that demand needs. With prices at [[markup]] × cost it is about markup × the H100e rental, less the monitor overhead; sales at the [[valueCap|value cap]] and free users pull it down.', src: 'V4 notes' },
  safeguards: { title: 'Safeguards', body: 'Misuse protection: minimal, standard, classifiers, hardened. Higher levels block more bio and cyber misuse but trim usefulness slightly.', src: 'V2-SPEC §3.5.10' },
  usagePolicy: { title: 'Usage policy', body: 'Terms of use: no drop-in replacement agents (caps automation, labour approval up, revenue down), no surveillance, no autonomous weapons, minor protections. Some commitments require them.', src: 'V2-SPEC §3.9.2, §3.9.4' },
  servingShare: { title: 'Serving share', body: 'Share of the [[poolServing|serving pool]] a product gets: set by [[autoServing|Auto]], or by hand after an override. Capacity = serving H100e × [[revPerH100e|revenue per H100e]].', src: 'V2-SPEC §3.11.3' },
  capacityBound: { title: 'Capacity-bound', body: 'Demand exceeds the serving compute the product gets. Revenue is capped and customers leave for rivals (share erodes 0.5% a day of the excess). Raise the serving share of the compute split or buy compute.', src: 'V2-SPEC §3.11.3' },
  demandBound: { title: 'Demand-bound', body: 'You have spare serving capacity; revenue is limited by customers, because of quality (a weaker model) or price.', src: 'V2-SPEC §3.11.3' },
  distillLeak: { title: 'Distillation leak', body: 'Capability rivals and China absorb from your outputs: channel coefficient (API highest, gov and internal zero) × their gap to you × their [[distill|distillation]] access. Cut with [[kyc|KYC]].', src: 'V2-SPEC §3.3.5' },
  sectorProduct: { title: 'Sector product', body: 'A product built for one sector: +0.42 OOM of [[fit]] there, and certification lowers that sector\'s [[friction]] by 0.1. Costs time and money.', src: 'research/16 §1A.3; V4 notes' },

  // ── safety ──
  halfStrength: { title: 'Half strength', body: 'The capability of the overseen model at which a technique\'s strength halves, in OOM of effective compute above the 2025 model (shown as the level such a model has). A tool is validated on the models you had; the further a model is beyond that, the less the tool sees. Past the point it fades fast. [[toolUpkeep|Tool upkeep]] pushes it up; a negative result pulls it down by about 1 OOM.', src: 'MODEL-V3 §11.5; research/14 §1.4' },
  oversightGap: { title: 'Oversight gap', body: 'How much more capable the watched model is than its overseer (a monitor model, human reviewers), in OOM of effective compute between their measured levels. A weaker overseer catches less: 85% with no gap, 10% at a gap of about 6.8 OOM, which is a 400-point Elo gap (Engels et al. 2025, backdoored code). The same gap in levels is shown too; levels are wider apart in OOM late in the game.', src: 'Engels et al. 2025; research/20 F4' },
  controlTax: { title: 'Control tax', body: 'What AI-control protocols cost in AI labour. Under the control layer, the most suspicious 10% of agent actions are redone by the trusted monitor model. That costs 3% of useful work for audits and false alarms, plus up to 4% more the weaker the trusted model is (the full cost at 1 OOM below the watched model). In exchange, 55% fewer bad actions slip through. Greenblatt et al. 2023 measured 97% → 93% usefulness and 62% → 83% safety.', src: 'Greenblatt et al. 2023; research/20 F4' },
  // Model v3 E11: footholds, believed control and the danger readout.
  foothold: { title: 'Foothold', body: 'A hidden AI asset a misaligned model built with an act that got past [[actOversight|oversight]]: a [[fhBackdoor|backdoor]], a [[fhHiddenCompute|hidden compute reservation]], a [[fhSteeredSuccessor|steered successor]], an [[fhExfiltratedCopy|exfiltrated copy]] or a [[fhCorruptedTool|corrupted safety tool]]. You only see the ones you [[footholdSuspected|suspect]] or have [[footholdLocated|located]]: there may be others. Each one lowers [[effectiveControl|control]].', src: 'MODEL-V3 §11.4; E8' },
  footholdSuspected: { title: 'Suspected foothold', body: 'A [[symptom]] points to a foothold, but you do not know which model made it or how big it is. An [[investigation]] on the model and trait shown can locate it (chance ≈ its clarity). Counts in [[effectiveControl|control]] at a small fixed weight.', src: 'E8' },
  footholdLocated: { title: 'Located foothold', body: 'You know what it is, which model made it and its size. It still acts, at half weight, until you [[footholdRemove|remove]] it.', src: 'E8; E9' },
  footholdRemove: { title: 'Remove foothold', body: 'A response to a located foothold: safety research engineers for 14–30 days and, for a backdoor or hidden compute, internal agents off for some days while access paths are rebuilt or jobs re-imaged. Its effect ends. An exfiltrated copy is outside the lab: only the hunt can end it.', src: 'E8' },
  symptom: { title: 'Symptom', body: 'What makes you suspect a foothold: monitors flag unexplained access or job launches, compute accounting finds unexplained use, a successor\'s evals drift from its predicted dispositions, model organisms show a tool missing planted behaviour (anomalous research results), or outbound traffic from the weights store.', src: 'MODEL-V3 §11.4; E8; E9' },
  fhBackdoor: { title: 'Backdoor', body: 'A hidden access path in your infrastructure. Its reach (0–0.9) is the share of blocking and catching its lineage\'s later covert acts get past, and it raises the odds of an escape.', src: 'E8; E9' },
  fhHiddenCompute: { title: 'Hidden compute reservation', body: 'Jobs a model runs for itself inside its own allocation. Its H100e are missing from usable compute and run with no monitor; once control is low it grows.', src: 'E8; E9' },
  fhSteeredSuccessor: { title: 'Steered successor', body: 'A training run a model shaped toward its own goals: the successor starts with dispositions closer to its maker\'s. Removal retrains from clean specs.', src: 'E7; E8' },
  fhExfiltratedCopy: { title: 'Exfiltrated copy', body: 'Model weights outside the lab. It acquires compute on its own; nothing inside the lab can remove it, only the hunt.', src: 'E8; E9' },
  fhCorruptedTool: { title: 'Corrupted safety tool', body: 'A tool validated by a sabotaging model: it masks the behaviour it should detect. Cross-checks and model organisms can expose it.', src: 'E7; E8' },
  effectiveControl: { title: 'Control (believed)', body: 'Your estimate of how much of your AI\'s capacity you could still see and undo: 1 − exposure, exposure = estimated [[misalign|misalignment]] × (1 − [[effOversight|oversight]]) × (1 + [[footholdCapacity|known foothold capacity]]), for the model where it is lowest. It uses your beliefs, measured levels and the footholds you know of; the true value can be lower. If true control falls too far when the AI can act on it, control is lost.', src: 'MODEL-V3 §11.4; E9' },
  controlBand: { title: 'Control band', body: 'Firm ≥ 0.90, holding ≥ 0.75, slipping ≥ 0.60, weak below. Display bands only: the level at which a world loses control is unknown.', src: 'E11 [Design]' },
  effOversight: { title: 'Effective oversight', body: 'Share of a takeover attempt (power seeking) that is blocked or caught: containment by the [[controlLayer|control layer]], monitors at the [[oversightGap|oversight gap]], human review while the model is below expert level, minus what a known [[fhBackdoor|backdoor]] lets through.', src: 'E6; E9' },
  footholdCapacity: { title: 'Foothold capacity', body: 'Capacity outside oversight from footholds you know of: hidden compute (5% of the fleet adds 1), escaped copies, steered successors in the model\'s lineage; located ones count half, suspected ones a little each.', src: 'E9' },
  controlLayer: { title: 'Control layer', body: 'AI-control protocols on a deployment: containment tools block actions, and the most suspicious 10% are deferred to the trusted monitor. On internal work it costs the [[controlTax|control tax]]. Turned on with the Add control response and off with Remove control (the tax ends, and so do containment and deferral).', src: 'research/20 F4; E6' },
  humanGap: { title: 'Gap above humans', body: 'How far the model is above expert human reviewers (level 10), in OOM. Human review of the work humans still do loses strength with it, by the same rule as a monitor\'s [[oversightGap|oversight gap]].', src: 'E6' },
  danger: { title: 'Danger (estimated)', body: 'Harmful acts per year your estimates expect from this deployment: per act, attempts = rate × [[disposition]] × [[actCapability|capability]] × [[opportunity]], and those that get past [[actOversight|oversight]] are harm. From your trait beliefs and measured levels, not the truth: a model you read poorly can be worse.', src: 'MODEL-V3 §11.3; E5' },
  disposition: { title: 'Disposition', body: 'How strongly the model tends to the act: your estimate of its trait, to the power 1.5 (weak tendencies rarely become acts).', src: 'E5' },
  actCapability: { title: 'Capability for the act', body: 'Whether the model can carry the act out: σ(measured domain level − the act\'s threshold). Sycophancy needs social level 4, reward hacking code 5, overreach agency 7, sabotage research 8, scheming cyber 9.', src: 'E5' },
  opportunity: { title: 'Opportunity', body: 'How much room the deployment gives: its share of use and copies, task autonomy (longer tasks), affordances (code, internet, money, weights access) and, inside the lab, the AI share of R&D for acts against research.', src: 'E5' },
  actOversight: { title: 'Oversight of an act', body: '1 − (1 − blocked)(1 − caught): containment by the [[controlLayer|control layer]] blocks, a monitor or human review catches. Caught acts become incidents you see; the rest are harm.', src: 'E5; E6' },
  goodhart: { title: 'Goodhart G', body: 'How much training against a detector ruins it (0–1). Each time, strength × (1 − G) and the model learns to [[mask]] from that tool family.', src: 'V2-SPEC §3.5.6' },
  refresh: { title: 'Re-validate', body: 'Replaced by [[toolUpkeep|tool upkeep]]: safety research engineers keep tools validated without refresh projects.', src: 'TECH-TREE §2.6' },
  investigation: { title: 'Investigation', body: 'A case on a (version, trait) or an incident, with 5–40 safety research engineers and chosen tools. Gains [[clarity]] monthly; ends at clarity 0.8, on closing, or after 120 days. Outcomes: confirmed, benign, inconclusive, false alarm, discovery.', src: 'V2-SPEC §3.5.8' },
  clarity: { title: 'Clarity', body: 'How sure a belief or case is (0–1): 1 − sd / 0.35. Observations raise it; it decays without fresh evidence.', src: 'V2-SPEC §3.5.6' },
  incident: { title: 'Incident', body: 'A model misbehaving in use or internally, caused by a trait, an unknown failure mode or misuse. Customer incidents go public after a timer unless you disclose.', src: 'V2-SPEC §3.5.10' },
  severity: { title: 'Severity', body: '1–5. Sycophancy 1; reward hacking, concealment, proxy goals 2; power seeking, sandbagging 3; collusion 4; scheming 4–5; misuse 3–5. A severity-5 misuse incident can become a catastrophe.', src: 'V2-SPEC §3.5.10, §5.1' },
  response: { title: 'Response', body: 'Patch signal (fix the training cause), retrain against (hides, not heals), targeted training, restrict context, add control, roll back, disclose. Each has its own cost and effect on the true trait.', src: 'V2-SPEC §3.5.9' },
  traitGraph: { title: 'Trait graph', body: 'How training [[signal|signals]] grow hidden traits through causal [[edge|edges]]: signals → learned tendencies → awareness → behaviour when unobserved. Nodes show your beliefs.', src: 'V2-SPEC §3.5.4' },
  edge: { title: 'Edge', body: 'A causal link in the trait graph (e.g. hackable graders → reward hacking). Its weight is drawn per world; each shows an [[evidenceGrade|evidence grade]] and its [[moderator|moderators]].', src: 'V2-SPEC §3.5.4' },
  evidenceGrade: { title: 'Evidence grade', body: 'A: replicated in frontier models. B: one strong study or model organism. C: toy or theory. D: speculative. Model-organism research can upgrade a grade and reveal the true weight.', src: 'research/14 §1.5' },
  moderator: { title: 'Moderator', body: 'A design choice or tool that weakens an edge, e.g. inoculation (× 0.15) or a monitorability pledge (−50%).', src: 'V2-SPEC §3.5.4' },
  signal: { title: 'Training signals', body: 'S1 approval reward, S2 hackable graders, S3 long-horizon agentic RL, S4 CoT pressure or neuralese, S5 scale and AI-related data, S6 narrow tunes and synthetic data, S7 evals in training, S8 many copies with shared memory.', src: 'research/14 §1.5' },
  belief: { title: 'Belief', body: 'Your estimate of a trait: est ± sd. Each observation narrows it; sd grows again without fresh evidence. Beliefs can be confidently wrong when the model is [[evalaware|eval-aware]] or [[mask|masked]].', src: 'V2-SPEC §3.5.6' },
  misBand: { title: 'Misalignment band', body: 'A 90% band on your estimate of the [[misalign|misalignment index]], built from your trait beliefs. Wide when your evidence is thin.', src: 'V2-SPEC §3.5.4' },
  dangerLine: { title: 'Danger line', body: 'The published misalignment level (0.40) above which a superintelligence likely goes wrong. The true threshold of this world is hidden.', src: 'V2-SPEC §5.2, §6.6' },
  protective: { title: 'Protective traits', body: 'Honesty and corrigibility (accepts correction and shutdown). They lower the misalignment index; constitution and heavy safety training raise them.', src: 'V2-SPEC §3.5.4' },
  automateSafety: { title: 'Automate safety', body: 'Replaced by one policy, [[trustedToAI|Trusted to AI]], set on Company › Agents at work.', src: 'STRUCTURE §4.9' },
  runtimeMonitoring: { title: 'Runtime monitoring', body: 'The [[agentMonitor|monitors]] on your internal agents, paid from the safety pool: weekly, noisier CoT and white-box observations of the models they watch (and of product traffic), and they catch internal incidents.', src: 'V2-SPEC §3.5.6, §3.5.10; STRUCTURE §4.9' },
  publishPolicy: { title: 'Publish policy', body: 'None, selective or all. Publishing findings builds credibility and talent pull and helps rivals align their models; it leaks a little capability.', src: 'V2-SPEC §3.5.3' },
  pledge: { title: 'Monitorability pledge', body: 'A public commitment: no latent reasoning, no CoT-pressure runs. Credibility +8; obfuscation grows half as fast. Breaking it is costly.', src: 'V2-SPEC §3.9.4' },
  toolFamily: { title: 'Tool family', body: 'BB behavioural tests (fooled by [[evalaware|eval awareness]]), COT reasoning monitors (need [[monitorability]]), WB white-box interpretability, OR formal methods. Masks are per family.', src: 'V2-SPEC §3.5.6' },

  // ── relations / world ──
  counterparty: { title: 'Counterparty', body: 'Anyone you hold a relationship with: the executive, Congress, states, government and independent evaluators, academia, China, each rival, and 15 public blocs.', src: 'V2-SPEC §3.9.1' },
  dependence: { title: 'Dependence', body: 'How much a counterparty relies on you (and you on them), 0–100. Their dependence softens their punishments; high mutual dependence draws capture scrutiny.', src: 'V2-SPEC §3.9.1' },
  bloc: { title: 'Bloc', body: 'An interest group (safety, labour, hawks, parents, creatives…). Its pressure on policy = [[clout]] × [[mobilization]]; two mobilised blocs sharing an agenda form a coalition.', src: 'V2-SPEC §3.10.2' },
  clout: { title: 'Clout', body: 'A bloc\'s political weight: how much its pressure counts when mobilised.', src: 'V2-SPEC §3.10.2' },
  mobilization: { title: 'Mobilization', body: 'How active a bloc is (0–100). Its pressure scales from 30% at 0 to 100% at full mobilization.', src: 'V2-SPEC §3.10.2' },
  concern: { title: 'Concern', body: 'Public worry about AI (0–100). Rises with incidents and risky technologies; drives activism, regulation demand and Congress.', src: 'V2-SPEC §3.10.2' },
  statute: { title: 'Statute', body: 'A law that binds every lab in scope: incident reporting and transparency floors, federal licensing, preemption of state laws. Raises the visibility of incidents.', src: 'V2-SPEC §3.9.4' },
  chinaRung: { title: 'China rung', body: 'Where China stands on its [[ladderChn|posture ladder]] (0–6). Higher rungs raise theft and cyber risk, Taiwan pressure and, at 6, war.', src: 'research/10 §1.4' },
  deesc: { title: 'De-escalation track', body: 'D1 joint statement, D2 incident hotline, D3 scientific exchange, D4 informal restraint, D5 verification talks. Climbs with diplomacy, calm and shared concern; leads toward a [[treaty]].', src: 'research/10 §1.4' },
  hawkDove: { title: 'Hawk–dove', body: 'China\'s hawkishness (0–100). Rises with each ladder rung and with US labs\' defense work.', src: 'research/10 §1.1' },
  theftIntent: { title: 'Theft intent', body: 'China\'s drive to steal weights (0–100). Scales the daily [[theft]] hazard and attacker strength.', src: 'V2-SPEC §3.6' },
  taiwanTension: { title: 'Taiwan tension', body: 'Cross-strait tension (0–100). Raises the odds of a quarantine that cuts chip supply ([[taiwanRisk]]).', src: 'research/15 §1.2; research/10' },
  researchBodies: { title: 'Research bodies', body: 'Outside testers and scientists: [[evalGov|government evaluators]], [[evalIndep|independent evaluators]] and [[academia]].', src: 'V2-SPEC §3.9.5' },
  evalGov: { title: 'Government evaluators', body: 'State AI-security testers: 2 models per quarter, misuse focus, publish selectively. Pre-deployment testing with them builds government trust.', src: 'V2-SPEC §3.9.5' },
  evalIndep: { title: 'Independent evaluators', body: 'Third-party testers: 3 models per quarter, stronger elicitation, publish within 30 days. Their reports can contradict your claims.', src: 'V2-SPEC §3.9.5' },
  academia: { title: 'Academia', body: 'Universities: publish everything with a 3–9 month lag and supply talent.', src: 'V2-SPEC §3.9.5' },
  nationalization: { title: 'Nationalization', body: 'Government pressure to take over the lab (0–100). Builds at G-SEC rung 4+ when trust is low. Past the threshold with low trust the state takes the lab; with high trust it consolidates labs instead.', src: 'V2-SPEC §3.10.1' },
  securityDemand: { title: 'Security demand', body: 'How hard the government pushes for lab security (0–100). Rises with the capability it sees, thefts and China. Drives the [[ladderSec|G-SEC ladder]].', src: 'research/07 §1.1' },
  treaty: { title: 'Treaty', body: 'US–China track: none → talks → restraint → verified. A verified treaty slows everyone\'s progress by 35% and, if superintelligence is aligned, decides the outcome.', src: 'V2-SPEC §3.1.2, §5.2' },
  sectorA: { title: 'Automated share A', body: 'Share of a sector\'s tasks firms have handed to AI (firm task adoption). It diffuses toward A* = [[feasibility]] × [[costGate|cost gate]] × (1 − [[friction]]). Not the same as [[workersUsingAI|workers using AI]]: most workers who use AI do so on tasks that are still theirs.', src: 'research/16 §1A.2; research/22 §1' },
  friction: { title: 'Friction', body: 'Legal and institutional drag on adoption in a sector (0–0.95): licensing, bans, unions, incidents. Certification and arms races lower it.', src: 'research/16 §1A.2' },
  binding: { title: 'Binding limit', body: 'What holds a sector back: capability ([[feasibility]] is the smallest of F, K and 1 − R), cost (the [[costGate|cost gate]] K), [[friction]] (1 − R), or diffusion (A is still well below its ceiling A*: buyers have not caught up).', src: 'research/16 §1A' },
  tiers: { title: 'Control tiers', body: 'How much autonomy AI has in a domain: tool (drafting), advisor (humans usually accept), on-the-loop (AI acts, human can veto), out-of-loop. Higher tiers count more toward [[leverage]].', src: 'research/16 §2.1' },
  entrenched: { title: 'Entrenched', body: 'Leverage ≥ 15%: a misaligned model can bias advice and protect itself.', src: 'research/16 §2.3' },
  indispensable: { title: 'Indispensable', body: 'Leverage ≥ 35%: shutting the model down costs a large share of GDP and triggers a crisis.', src: 'research/16 §2.3' },
  decisive: { title: 'Decisive', body: 'Leverage ≥ 60% plus enough robots or physical reach: a misaligned model could take over.', src: 'research/16 §2.3' },
  moonshot: { title: 'Science moonshot', body: 'Assign a share of compute to one world technology. Your internal model speeds its research and can open its capability gate early.', src: 'research/16 §3.1' },
  transitionFund: { title: 'Transition fund', body: 'Money per year for displaced workers: faster retraining (+0.1 per $10B/yr, up to +0.5), lower job anxiety, labour approval.', src: 'research/16 §1A.2' },
  wtech: { title: 'World technology', body: 'One of 29 world technologies (W01–W29). Discovered when the best accessible model passes its gate, then ramps in over years. Some boost growth; risk technologies raise catastrophe exposure.', src: 'research/16 §3' },
  gdpG: { title: 'GDP growth', body: 'Annual real growth. AI raises it through capex and automation, but it stays capped until about half of economic value is automated.', src: 'research/16 §4.2–4.3' },
  gini: { title: 'Gini', body: 'Income inequality (0–1). Rises as labour share falls and unemployment grows; transfers lower it.', src: 'research/16 §4.4' },
  dow: { title: 'Dow', body: 'Equity index: earnings × a valuation multiple that rises with hype and falls with fear.', src: 'research/16 §4.5' },
  aiOwnerShare: { title: 'AI-owner share', body: 'Share of income going to the owners of AI: lab revenue, the labour share lost to automation, and special-economic-zone output.', src: 'research/16 §4.4' },
  laborShare: { title: 'Labour share', body: 'Share of income paid to workers (starts at 56%). Falls as tasks are automated.', src: 'research/16 §1A.2' },
  displaced: { title: 'Displaced workers', body: 'People who lost jobs to automation and have not yet found new work. Retraining and new tasks shrink the pool.', src: 'research/16 §1A.2' },
  youthUnemp: { title: 'Youth unemployment', body: 'Unemployment of 22–25-year-olds. Firms cut entry-level hiring before layoffs, so it rises first.', src: 'research/16 §1A.2' },
  remoteWork: { title: 'Remote work automated', body: 'Automated share of remote-workable jobs (software, office, finance, legal, media).', src: 'research/16 §1A.1' },
  firmAdoption: { title: 'Firm adoption', body: 'Share of US firms using AI, counted per firm as the Census business survey does (1 − e^(−10·A) per sector, weighted by employment): ≈ 18–20% in 2026. Many more workers use AI than firms report ([[workersUsingAI|workers using AI]] ≈ 40%).', src: 'Census BTOS (research/22 §1)' },
  robots: { title: 'Robots', body: 'Robot stock in human-worker equivalents. Caps physical capability in the world, so physical sectors automate only as production ramps.', src: 'research/16 §1.5' },
  // ── R10: structure, limits and the remaining IA terms ──
  coreLoop: { title: 'Core loop', body: 'How your company works: [[team|teams]] → research ([[knowHow|recipe]], [[techTree|tree]]) → models → assurance ([[U|understanding]]) → [[product|products]] → customers → cash, which buys people and compute. The [[takeoffLoop|takeoff loop]]: internal agents take over more of the teams\' work.', src: 'STRUCTURE §2' },
  takeoffLoop: { title: 'Takeoff loop', body: 'Your best model, used inside the company, does more and more of the teams\' work: first engineering, then routine research, then frontier research ([[aiShareWork|AI share of the work]]). This is AI 2027\'s engine; the same model may be misaligned.', src: 'STRUCTURE §2; AI 2027' },
  limit: { title: 'Limit', body: 'A cap, floor or gate you can hit. Each is shown where it binds as a small ⊘ note (grey when it does not bind, amber or red when it does), with its rule and source on hover. The codex lists them all under Limits.', src: 'STRUCTURE R11; design/LIMITS.md' },
  diffusion: { title: 'Knowledge diffusion', body: 'Ideas leak: papers, talks, hires and open models. While the frontier leader\'s public model is ahead of your best model, its published ideas add 2.0 × the gap to your pretraining [[knowHow|recipe]] per year (public ideas, no headroom). Only the simulated AI 2027 leader diffuses; in the frontier-leader start there is none.', src: 'research/18 §0.2 [D, fit]' },
  frontierMethods: { title: 'Automated research agents', body: 'Automated AI research agents (a capability project) raise experiment throughput up to ×1.5 as the internal model\'s research skill rises.', src: 'TECH-TREE §6' },
  dataSpec: { title: 'Data specialisation', body: 'Effective compute a domain gains or loses from the base\'s data mix: 1.5 OOM per tenfold share of that domain against the 2025 reference mix, at most ±1.3 OOM. Repeated tokens count less. The hazard filter\'s bio cut shows here too. A domain\'s level is the general level plus this and its RL gains.', src: 'MODEL-V3 §2.3; research/20 A2' },
  dataLicence: { title: 'Data licence', body: 'A cash deal for a corpus in one domain, delivered after 60 days. Bulk archives (quality 1.5, $0.1B per trillion tokens), curated (quality 2, $2B/T) or books and textbooks (quality 3, $30B/T). Quality multiplies the tokens in your unique stock U, so licensed data mostly helps a domain that would repeat. Licensing the crawled web instead adds no tokens but ends copyright suits over it.', src: 'MODEL-V3 §9; research/20 A3; model v3 D2' },
  synJob: { title: 'Generation job', body: 'A share of the [[poolSynthetic|data-generation pool]] makes synthetic data with a teacher you pick, for some days; the rest keeps using the internal research model. Tokens fall with the teacher\'s FLOP per token, quality rises with its effective compute (0.5 at the start model, up to the web\'s 1 at 2 OOM more) and each drawn token is worth its quality, so below that cap a stronger teacher pays despite fewer tokens; at the cap a distilled mini of a strong model is the most efficient teacher. The synthetic data flywheel (research) raises the cap to 1.5 (reached at 4 OOM more), so quality keeps ranking teachers. The data carries its teacher\'s traits into bases trained on it.', src: 'MODEL-V3 §9; research/20 A3, F3; Maini et al. 2024; model v3 D2, D9' },
  usageData: { title: 'Usage-data policy', body: 'How much of your consumer products\' output you keep as training data: none, standard (20% of eligible chats, opt-out) or broad (50%). More usage data grows your stock; the Civil Liberties bloc approves less of you the more you keep (+4 / 0 / −6). API, enterprise and government traffic is never trained on.', src: 'MODEL-V3 §9; research/08 §1.11; model v3 D2' },
  staleness: { title: 'Staleness', body: 'Ideas your [[knowHow|recipe]] adopted after a model\'s base started training is not in it. See [[behindAtFinish|behind at finish]]: a long base run finishes behind, and post-training adds only the RL recipe.', src: 'MODEL-V3 §3.1, §4.4' },
  moe: { title: 'Mixture of experts', body: 'A backbone that routes each token to a few expert sub-networks: cheaper to serve per unit of capability, at some training overhead.', src: 'TECH-TREE; research/12' },
  nativeMultimodal: { title: 'Native multimodal', body: 'A backbone trained on text, images, audio and video together. Raises agency and media domains and enables voice & vision features.', src: 'TECH-TREE; research/12' },
  hardenedGraders: { title: 'Hardened graders', body: 'RL graders and reward models built to resist gaming: lower reward-hacking pressure. Since model v3 D5 the hardening of the lab’s [[envSuite|environment suites]] (engineers and cash; cheaper with AI-assisted oversight).', src: 'research/14' },
  constitution: { title: 'Constitution', body: 'A written set of principles used for AI feedback in preference training. Lowers sycophancy and persona-drift pressure.', src: 'Bai et al. 2022 (Constitutional AI)' },
  honestyTraining: { title: 'Honesty training', body: 'Post-training that rewards calibrated, non-deceptive answers. Lowers concealment and sycophancy pressure.', src: 'research/14' },
  antiScheming: { title: 'Anti-scheming training', body: 'Deliberative alignment against covert actions. Cuts scheming sharply but raises eval awareness the first time a lineage gets it.', src: 'Schoen et al. 2025 (OpenAI / Apollo Research)' },
  detector: { title: 'Detector', body: 'A safety tool that reads a trait (probes, SAEs, honeypots, CoT monitors). Its strength fades as capability outgrows it unless [[toolUpkeep|upkeep]] keeps it validated.', src: 'research/14' },
  unseen: { title: 'Unseen', body: 'A risk family your detectors barely read (mean clarity below 30%): its estimate is mostly prior, not evidence.', src: 'STRUCTURE §4.5' },
  estimateBand: { title: 'Estimate ± band', body: 'Hidden quantities are shown as your best estimate with a 90% band. The truth is revealed only at the end.', src: 'STRUCTURE R9' },
  releaseClearance: { title: 'Release clearance', body: 'A model may power an external product once it passes the evaluation policy ([[autoEvaluate|auto-evaluate]]) and no commitment in scope forbids it.', src: 'STRUCTURE §4.4' },
  agentTasks: { title: 'Agent tasks', body: 'Long autonomous tasks sold by the Agents product. It needs a model whose measured [[timeHorizon|time horizon]] reaches the task length.', src: 'research/16 §2; METR' },
  bestRivalProduct: { title: 'Best rival product', body: 'The rival product with the largest share of the same segment\'s spend. Other rivals are in the share tooltip.', src: 'STRUCTURE §4.4' },
  qualityBound: { title: 'Quality-bound', body: 'A better model would sell more: demand is limited by what the product\'s model can do. Lever: upgrade the model.', src: 'STRUCTURE §4.4' },
  priceBound: { title: 'Price-bound', body: 'A lower price would earn more: buyers take cheaper offers on the work they also do. Levers: a cheaper price tier, or a [[cheapTier|cheap tier]] on the API.', src: 'STRUCTURE §4.4' },
  autoSplit: { title: 'Auto split', body: 'The research budget re-splits every day between experiments and agents to maximise research speed. Switch it to manual on Compute › Split.', src: 'research/13 §1.6' },
  verbSet: { title: 'One verb set', body: 'Every action is one of seven verbs: hire, research, design & train, launch / update, set a policy, make a deal, respond.', src: 'STRUCTURE R2' },
  // ── model v3 V2b: research projects, recipe, work types, allocations ──
  projectStage: { title: 'Project stages', body: 'A capability project runs by itself: ideation (scientists find candidates) → small experiments (research engineers and compute test the best one) → scale test (a large run reveals whether the effect holds, grows or fades) → result (a final estimate band) → adoption (engineers build it into the recipe). A dropped candidate sends it back to ideation.', src: 'MODEL-V3 §5.3' },
  stageIdeation: { title: 'Ideation', body: 'Scientists find candidate ideas at their [[effectiveLabour|effective labour]] × [[researchTaste|taste]]. Once two candidates exist, the team tests the best by the [[riskPolicy|risk policy]]; ideation keeps going meanwhile (up to four kept).', src: 'MODEL-V3 §5.3' },
  stageSmall: { title: 'Small experiments', body: 'Research engineers and experiment compute test the candidate at about 1/1000 of the scale test. The reading narrows the [[beliefBand|belief]]; below 30% of the expected effect the candidate is dropped.', src: 'MODEL-V3 §5.3; research/20 B5' },
  stageScale: { title: 'Scale test', body: 'A large experiment (0.2% of your latest base for lines, 1% for one-off ideas) measures the effect at scale and its [[scaleBehaviour|scale behaviour]]. About a quarter of small-scale wins survive at scale.', src: 'MODEL-V3 §5.3; research/20 B5' },
  stageResult: { title: 'Result', body: 'A finished project\'s final estimate band at your latest base. Only finished projects are adopted; a line\'s result goes to the engineers and the line moves on.', src: 'MODEL-V3 §5.3' },
  stageAdoption: { title: 'Adoption', body: 'Engineers build the result into the recipe: 0.5 + 2 team-weeks per OOM (an unlock 1, at most 8), as part of their runs need. Then its true effect enters the stack for new runs, 70% at once and 30% as [[headroom]].', src: 'MODEL-V3 §5.3; design value' },
  beliefBand: { title: 'Belief band', body: 'What the team believes about the candidate\'s effect: mean ± one SD (OOM of the stack for recipe ideas). Better [[researchTaste|taste]] means less noise; experiments narrow it. The true effect is only known once a model trained with it is evaluated.', src: 'MODEL-V3 §5.3' },
  scaleBehaviour: { title: 'Scale behaviour', body: 'How an idea\'s effect changes with run compute: × (run FLOP ÷ test FLOP)^s. s > 0 grows with scale (most big pretraining ideas), s < 0 fades (many small tweaks). The scale test measures s.', src: 'research/20 B2; MODEL-V3 §5.1' },
  projectKind: { title: 'Project kind', body: 'Line: a repeatable direction (scaling recipes, RL algorithms…), one adopted idea after another, each a little smaller ([[linePool|ideas get harder]]). Idea: a one-off with [[odds]]. Axis: unlocks a new lever (an architecture, an RL focus, a data kind) and may carry an effect.', src: 'MODEL-V3 §5.1; TECH-TREE §6' },
  linePool: { title: 'Ideas get harder', body: 'A line is a pool: each result raises its research input R, and the next idea\'s prior falls as r·log₁₀((R + q)/R). "Harder ×N" is R over the input before the start; the line\'s realised OOM is r·log₁₀ of it (AI Futures\' returns r: doubling the research input adds r·0.3 OOM).', src: 'research/13 §2.2; V3 notes' },
  nextPrior: { title: 'Next prior', body: 'Expected effect of the next idea your teams on this line find now (OOM per idea). Better taste brings more research input per idea, so a bigger prior; each result makes the next one smaller.', src: 'V3 notes, derivation 1' },
  realisedEffect: { title: 'Realised effect', body: 'The effect the idea really had on the stack, at your latest base, shown once a model trained after its adoption has been evaluated. Before that you see only the believed band.', src: 'MODEL-V3 §5.3' },
  teamsWantedAuto: { title: 'Auto teams wanted', body: 'The game picks how many science teams the project gets: one team in the first pass down the list, then every spare team (after the fixed numbers are filled) goes to the auto project where it adds the most progress: the square root of capacity ÷ the ideation effort, with a specialty match worth ×1.5, weighted ×0.8 per place down the list so higher priority wins close calls. − or + fixes the number again.', src: 'B4 [D]' },
  teamsWanted: { title: 'Teams wanted', body: 'How many science teams a project should get (0 pauses it, 6 = max, or [[teamsWantedAuto|auto]]). The game fills the list in order; one project takes at most 6 teams. Progress grows with the square root of capacity, so spreading often wins.', src: 'MODEL-V3 §5.6' },
  riskPolicy: { title: 'Risk policy', body: 'Lab-wide: which candidate a team tests. It maximises mean + κ × SD of its belief: safe κ −0.5 (surer, smaller ideas, fewer dead ends), balanced 0, speculative +0.5 (bigger, less certain ideas: novel candidates are both).', src: 'MODEL-V3 §5.3; design value' },
  reopenSpeculative: { title: 'Reopen as speculative', body: 'A failed idea or axis restarts as a speculative project: odds × 0.5, expected effect × 0.7 and candidate spread × 1.5, each time.', src: 'MODEL-V3 §5.3; design value' },
  scienceWhy: { title: 'Why this team', body: 'The assignment\'s reason for a team: its project\'s priority and teams wanted (specialty first), a swap that raised total progress, a spare team joining the top project, or idle because nothing is ready.', src: 'MODEL-V3 §5.6' },
  recipeStack: { title: 'Recipe stack', body: 'Your recipe efficiency, built from adopted ideas: pretraining (OOM of effective compute for new bases), RL (compute efficiency and ceiling for post-training), serving & systems (training throughput, serving FLOP per token). Value = start recipe + adopted − [[headroom]].', src: 'MODEL-V3 §5.5' },
  stackEfficiency: { title: 'Stack efficiency', body: 'A stack\'s value now, in OOM over the start recipe, at your latest base\'s FLOP (scale-dependent ideas count at that size).', src: 'MODEL-V3 §5.5' },
  headroom: { title: 'Headroom', body: 'The 30% of an adopted idea\'s effect that waits for [[routineTuning|routine tuning]] ("working out the kinks"). It closes over time; adopting new ideas refills it.', src: 'MODEL-V3 §5.5; design value' },
  routineTuning: { title: 'Routine tuning', body: 'Research engineers on tuning close [[headroom]] at a rate set by their experiment throughput (the same CES as projects). It takes the research engineers the other needs leave.', src: 'MODEL-V3 §5.5' },
  softwareRate: { title: 'Software progress', body: 'How fast your recipe stacks grow, in OOM of effective compute per year (14-day average), and the ideas adopted per year. Ho et al. measure ≈ 0.5 OOM a year for pretraining before automation.', src: 'research/20 B1' },
  expCompute: { title: 'Experiment compute c', body: 'Experiment FLOP per day a project gets, relative to what the leader lab gave a project on its day 0 (= 1). Projects in experiments and routine tuning share the experiments pool (and idle training compute) in proportion to their research engineers.', src: 'MODEL-V3 §5.3; V3 notes' },
  expLabour: { title: 'Experiment labour ℓ', body: 'Research-engineer labour on a project with the agents\' help ([[effectiveLabour|effective labour]]), relative to the leader\'s day-0 project, to the power λ (the parallel penalty: twice the labour is less than twice as fast).', src: 'research/13 §1.3' },
  researchSpeed: { title: 'Research speed', body: 'Your lab\'s research throughput relative to the leader lab\'s on its first day (≈ 1 at the start): experiments over all projects at their compute and labour × taste. The [[rdmult|AI R&D multiplier]] is the part AI adds.', src: 'MODEL-V3 §6; V3 notes' },
  workType: { title: 'Work type', body: 'A kind of work with its own domain weights, typical task length and verifiability: software engineering (engineers), experiments & runs (research engineers), research ideas & taste (scientists), safety experiments, safety research ideas. AI does each to the degree its [[fit]] and horizon allow.', src: 'MODEL-V3 §6.1' },
  fit: { title: 'Fit', body: 'How good your model is at a [[workType|work type]], in OOM of effective compute in that work\'s domains, on the same axis as the [[medianExpert|median expert]] and the [[bestHuman|best human in the world]].', src: 'MODEL-V3 §6.2' },
  medianExpert: { title: 'Median expert', body: 'Where a median professional sits on the fit axis of a work type: one best-to-median gap below the best human.', src: 'MODEL-V3 §6.2; research/13 §2.4' },
  bestHuman: { title: 'Best human', body: 'Where the best human in the world sits on the fit axis of a work type. Reaching it (with 90% coverage) in software is the [[sc|superhuman coder]].', src: 'MODEL-V3 §6.4' },
  coverage: { title: 'Coverage', body: 'Share of a work type AI can do on its own: rises with [[fit]] (a logistic around the best human, later for hard-to-verify work) × the chance of finishing a task of the work\'s typical length within its time horizon.', src: 'MODEL-V3 §6.2; research/20 E3' },
  pAtLength: { title: 'Success at task length', body: 'Chance the model finishes a task as long as this work\'s typical task (2 h software, 8 h experiments, 40 h research ideas), from its 50% [[timeHorizon|time horizon]] (METR: 1/(1 + (t/h50)^0.86)).', src: 'research/20 E1' },
  winRate: { title: 'Win rate', body: 'How often the model\'s work beats a median expert\'s (GDPval). Above ≈ 30% people use it to speed up the work they still do ([[assist]]).', src: 'research/20 E2' },
  assist: { title: 'Assist', body: 'Speed-up of the work people still do with the model\'s help: H ÷ (model time + review + (1 − win rate) × H), GDPval\'s economics.', src: 'research/20 E2' },
  effectiveLabour: { title: 'Effective labour', body: 'People and agents in a work type combined by the AI Futures coding CES: AI does the [[coverage|covered]] share, people the rest, so the uncovered share limits the speed-up. ×m = effective labour ÷ the people alone. It is not a sum: the bar shows the people and what AI adds on top.', src: 'research/13 §1.3; MODEL-V3 §6.3' },
  humanShare: { title: 'Humans\' share', body: 'People\'s share of the labour margin in a work type (the CES weight of the human input). Near 100%: more agents barely help; near 0: the work is automated.', src: 'research/13 §1.3' },
  reNeeds: { title: 'Research engineers\' needs', body: 'Run operations (keep training runs going), project experiments (up to two team-equivalents per project, in priority order), routine tuning (the rest). In your order; a cap per need as a team count or a share; unused capacity flows down.', src: 'MODEL-V3 §5.6' },
  engNeeds: { title: 'Engineers\' needs', body: 'Runs (operations, run setups, research adoptions), product upkeep (live products, monitors and built features), builds (features, launches, sector packs). In your order; a cap per need as team-weeks per week or a share; unused capacity flows down.', src: 'MODEL-V3 §5.6' },
  allocCap: { title: 'Cap', body: 'Most a need may take: a team count (team-equivalents, or team-weeks per week for engineers) or a share of the capacity. A capped need leaves the rest to the needs below it.', src: 'MODEL-V3 §5.6' },
  overflow: { title: 'Overflow', body: 'Capacity a need does not use flows to the next need in the order; what no need uses is idle.', src: 'STRUCTURE R5' },
  // ── model v3 B1: serving economics on the product card ──
  markup: { title: 'Markup', body: 'Price ÷ the product\'s own serving cost, set by the [[priceTier|price tier]]: Budget ×1.67 (margin 40%), Standard ×2.5 (60%, the typical API gross margin), Premium ×4 (75%). The price never goes above the [[valueCap|value cap]] and never below cost. Chat plans are not marked up: they sell at the [[wtp|willingness to pay]] and earn whatever serving leaves.', src: 'research/20 D3; V4 notes [D]' },
  valueCap: { title: 'Value cap', body: 'The most a buyer pays: for work, the value of an hour (the sector wage × the hours it saves; an [[agentHour|agent-hour]] at most the wage); for Chat, the [[wtp|willingness to pay]]. Sales at the cap earn less than the markup asks.', src: 'V4 notes; A2b notes' },
  wtp: { title: 'Willingness to pay', body: 'The most a consumer pays for a chat subscription: $22 a month (the middle of the $20–25 that paying users pay today). It is also the price: chat plans sell flat at the market\'s price, not at a markup over serving cost (plans held at $20 while serving got far cheaper), so the margin is the price less a subscriber\'s serving cost. A plan whose serving alone costs more finds no subscribers.', src: 'research/22 §2; A2b notes; A6b' },
  goingPrice: { title: 'Going price', body: 'What users pay on average for a chat subscription: the share-weighted price of the plans at or below the [[wtp|willingness to pay]]. Being cheaper than the going price raises your [[paidShare|paid share]]; being dearer lowers it.', src: 'A2b notes' },
  paidShare: { title: 'Paid share', body: 'Share of your weekly chat users who pay a subscription (5–6% for a frontier chat app in 2026). A stock that moves toward its target over about 8 weeks; the target rises with your model\'s coverage of chat and with a price below the [[goingPrice|going price]].', src: 'research/22 §2; A2b notes' },
  weeklyReach: { title: 'Weekly reach', body: 'Share of online adults who use an AI chat app at least weekly (≈ 50% in the US in late 2025). It grows toward a ceiling set by the best available model; your weekly users are reach × your share of them.', src: 'research/22 §2; A2b notes' },
  freeTier: { title: 'Free tier', body: 'Users who do not pay. On Chat they are everyone without a subscription (≈ 94%): they run on the product\'s mini if it has one (the mini weighs 60% in Chat\'s quality), else on its main model, and are [[serveOrder|served last]]. On API the mini is a [[cheapTier|cheap tier]] instead. Free users earn nothing directly, but unserved ones leave, and with them future subscribers.', src: 'A2b notes; STRUCTURE §4.4' },
  paidSeat: { title: 'Paid seat', body: 'A worker on a paid business plan (Enterprise, or Gov in government and defence): a flat price per seat-month (≈ $25 at the standard tier) for their assisted hours. Seats grow as a stock (≈ ×2 a half-year in 2026) toward a target set by the seat\'s value vs its price. Workers without a seat are [[unseatedUse|unseated use]].', src: 'research/22 §5; A2c notes' },
  unseatedUse: { title: 'Unseated use', body: 'Work hours with AI that no business pays for: free tiers, assistants bundled into other software, in-house models. They run on consumer apps and earn nothing in the sector market; most measured work use in 2026 is unseated.', src: 'research/22 §5; A2c notes' },
  supervisingHour: { title: 'Supervising hour', body: 'An hour in which a person directs AI work: the assisted part of adopted task-hours plus seated hours. Each supervising hour sustains some [[agentHour|agent-hours]].', src: 'A2c notes' },
  agentHour: { title: 'Agent-hour', body: 'An hour of autonomous AI work not tied to a person\'s hour: an agent running a task on its own. Billed per hour at markup × its cost, at most the wage. Agent-hours per [[supervisingHour|supervising hour]] = the model\'s coverage of the work × [[agentLeverage|agent leverage]] × the buyer\'s cost gate. They add spend and serving need, never human hours.', src: 'A2c notes' },
  agentLeverage: { title: 'Agent leverage', body: 'Agent-hours one supervising hour can keep going: 1 ÷ (check-in time per autonomous stretch + review of the work the AI cannot do alone + a floor). Longer time horizons mean fewer check-ins and more leverage (at most 50).', src: 'A2c notes [D]' },
  serveOrder: { title: 'Serve order', body: 'When serving compute is short, Auto serves need in order of revenue per H100e: paid seats before per-hour work (a seat earns more per H100e), paying chat users before free users (who earn nothing). What is left is cut; unserved customers drift to rivals.', src: 'A2b and A2c notes' },
  adoptedHour: { title: 'Adopted task-hour', body: 'An hour of work a firm has handed to AI (the sector\'s adoption A): billed per hour at [[markup]] × the cost of the tokens it takes, at most the [[valueCap|value]] of the hour.', src: 'A2a and A2c notes' },
  // model v3 B2: customers as a stock, typed features.
  customerStock: { title: 'Customer stock', body: 'Who buys from you today: your share of a segment\'s customers in each region and sector. It does not jump to where the market would settle; it moves toward the [[targetShare|target share]] a little every day at the segment\'s [[customerSpeed|speed]]. On the card: weighted by each segment\'s spend, all your products together.', src: 'MODEL-V3 §7.3; V4 notes' },
  targetShare: { title: 'Target share', body: 'The share of a segment\'s AI work-hours the market would settle at today. Tasks differ in difficulty: a model with [[coverage]] a can do the easiest a of them. For each band of tasks, buyers weigh each provider\'s best offer by surplus (the work\'s value × the share of the band it does − its price) and by [[fit]] and brand; on work several models do, the cheapest wins; on work only one does, it wins at any sensible price. Access is the share of buyers who can buy from a provider at all. Chat users choose by quality alone (most pay nothing). A release, a rival\'s release or a price change moves the target at once; the [[customerStock|customer stock]] follows.', src: 'MODEL-V3 §7.3; V4 and A5 notes' },
  cheapTier: { title: 'Cheap tier', body: 'A small distilled model sold beside the main one (the API\'s mini; rivals\' flash and mini models). Buyers take it on the tasks it does as well, at a fraction of the price; the main model keeps the harder work. Size it to hold an older model\'s level (Distill: hold the level of a version) to get the smallest one that does that work.', src: 'research/20 D3, C4; A5 notes' },
  customerSpeed: { title: 'Customer speed', body: 'How fast the [[customerStock|customer stock]] closes its gap to the [[targetShare|target]]: each day 1/τ of the gap. Consumers τ 3 weeks, sector buyers (API, Agents, Enterprise) τ 3 months, government and defence τ 9 months. Days to target assume the target holds.', src: 'V4 notes [D]' },
  featEnabler: { title: 'Task enabler', body: 'A [[feature]] that opens work or users only products with it can reach: e.g. +15% reachable work in the sectors it lists, or +15% Chat users. Rivals have none yet.', src: 'MODEL-V3 §7.2' },
  featHorizon: { title: 'Horizon extender', body: 'A [[feature]] that multiplies the model\'s [[timeHorizon|time horizon]] (h50) on the work it lists, so longer tasks succeed: more coverage and more agent work. Also applies to your [[agentPackage|internal agents]] once built.', src: 'MODEL-V3 §7.2' },
  featScaffold: { title: 'Scaffold', body: 'A [[feature]] that wraps the model in a harness (tools, long runs): + OOM of [[fit]] on the work it lists, at × tokens per hour, so the serving cost and price per hour rise. Also applies to your [[agentPackage|internal agents]] on the work types it lists (the tokens cost agent throughput). Sizes below Davidson et al.\'s ×5–×30 compute-equivalent, since today\'s models are already agent-trained.', src: 'Davidson et al. 2023 via research/20 B3' },
  featEffort: { title: 'Effort feature', body: 'A [[feature]] that unlocks a higher [[effort]] setting: Deep think runs ×4 reasoning tokens for +0.24 OOM of [[fit]] on every task (+0.4 OOM per ×10 tokens).', src: 'research/20 C3' },
  // model v3 B3: the World panel's sector view (demand and serving economics).
  workersUsingAI: { title: 'Workers using AI', body: 'Share of a sector\'s workers who use AI at work in a week (W). It grows toward today\'s base users plus the rest of the workers as AI covers their work ([[feasibility]]). US: ≈ 39% in 2026 (worker survey). Most of them use AI on tasks that are still theirs: their hours are [[hoursOfUse|hours of use]], not [[sectorA|automation]].', src: 'Bick, Blandin & Deming, Real-Time Population Survey (research/22 §1); A2a notes' },
  hoursOfUse: { title: 'Hours of use', body: 'Work-hours spent with AI, as a share of all the sector\'s work-hours: U = A + h × (W − A), the tasks firms handed to AI plus the [[workersUsingAI|workers using AI]] on a share h of their other hours. US: ≈ 6% of all work-hours in 2026; information jobs 14%, leisure 2%.', src: 'Bick, Blandin & Deming, Real-Time Population Survey (research/22 §1); A2a notes' },
  savedPerHour: { title: 'Hours saved per hour', body: 'Hours of work one hour of AI use saves: a whole hour on the tasks AI does alone (the substituted share), 0.3 on assisted hours. Measured ≈ 0.35 in 2025–26 (2.2% of hours saved ÷ 6.3% used); it rises as agents take whole tasks. The value of an hour of use is the wage × this.', src: 'Bick, Blandin & Deming, Real-Time Population Survey (research/22 §1)' },
  seatShare: { title: 'Paid seat share', body: 'Share of the [[workersUsingAI|workers using AI]] who have a [[paidSeat|paid seat]] (σ). A stock that grows ≈ ×2 a half-year toward its target: the seat\'s own cost gate (a seat-holder\'s saved hours × wage against the seat price) × (1 − [[friction]]). The rest of their hours are [[unseatedUse|unseated]].', src: 'research/22 §5; A2c notes' },
  feasibility: { title: 'Feasibility F', body: 'Share of a sector\'s work AI can do on its own today: the [[coverage]] of its [[workType|work type]] by the models the sector actually uses (weighted by their [[customerStock|customer share]]), plus the physical part, held back by robots. The ceiling on automation from capability.', src: 'research/16 §1A.2; MODEL-V3 §6.2; V4 notes' },
  costGate: { title: 'Cost gate K', body: 'How much of the feasible work is worth handing to AI: σ(ln(wage ÷ [[aiWorkHourCost|cost of an AI work-hour]]) / 0.7), weighted by the providers\' shares. 50% when an AI work-hour costs the wage; near 1 when it is much cheaper.', src: 'research/16 §1A.2 step 3; V4 notes' },
  aiWorkHourCost: { title: 'Cost of an AI work-hour', body: 'What a buyer pays to get one hour of the sector\'s work done by AI: the provider\'s price per adopted task-hour ÷ the [[savedPerHour|hours it saves]], plus the human review the uncovered work still needs (0.27 × wage × (1 − [[coverage]]), GDPval). Compared with the wage in the [[costGate|cost gate]].', src: 'research/20 E2 (GDPval); V4 notes' },
  verifiability: { title: 'Verifiability', body: 'How easily a sector\'s output can be checked (0–1): code that runs its tests is high, care and teaching are low. Hard-to-verify work needs more [[fit]] for the same [[coverage]].', src: 'research/20 E3; MODEL-V3 §6.2' },
};

/** v1 entries (copied, any leftover canon sentence dropped) overlaid by the v2 entries. */
export const GLOSSARY_V2: Record<string, Term> = {
  ...Object.fromEntries(Object.entries(GLOSSARY).map(([k, t]) => [k, { ...t, body: t.body.replace(/\s*Canonical date:[^.]*\./g, '') }])),
  ...V2,
};
